#[test]
fn test_keyless_conflicts_read_each_side_s_row_in_its_own_layout() {
    run_scripts(&[ScriptTest {
        name: "a keyless table's merge conflict shows the base's and their rows when our side changed its columns",
        set_up_script: &[
            "CREATE TABLE t (a int, b int);",
            "INSERT INTO t VALUES (1, 1), (1, 1);",
            "SELECT dolt_commit('-Am', 'base');",
            "SELECT dolt_branch('right');",
            "SELECT dolt_checkout('right');",
            "INSERT INTO t VALUES (1, 1);",
            "SELECT dolt_commit('-Am', 'right');",
            "SELECT dolt_checkout('main');",
            "ALTER TABLE t ADD COLUMN c int;",
            "DELETE FROM t WHERE ctid = (SELECT min(ctid) FROM t);",
            "SELECT dolt_commit('-Am', 'main');",
            "SET dolt_allow_commit_conflicts = 1;",
            "SELECT * FROM dolt_merge('right');",
        ],
        assertions: &[
            ScriptTestAssertion {
                query: "SELECT base_a, base_b, our_a, our_c, their_a, their_b, dolt_base_cardinality, dolt_our_cardinality, dolt_their_cardinality FROM dolt_conflicts_t;",
                expected: Expected::Rows {
                    columns: &[Column("base_a", INT4), Column("base_b", INT4), Column("our_a", INT4), Column("our_c", INT4), Column("their_a", INT4), Column("their_b", INT4), Column("dolt_base_cardinality", INT8), Column("dolt_our_cardinality", INT8), Column("dolt_their_cardinality", INT8)],
                    rows: &[
                        &[T("1"), T("1"), T("1"), Null, T("1"), T("1"), T("2"), T("1"), T("3")],
                    ],
                    tag: "SELECT 1",
                },
                ..A
            },
        ],
        ..S
    }, ScriptTest {
        name: "a keyless table's merge conflict resolved with their rows when their side changed its columns",
        set_up_script: &[
            "CREATE TABLE t (a int, b int);",
            "INSERT INTO t VALUES (1, 1), (1, 1);",
            "SELECT dolt_commit('-Am', 'base');",
            "SELECT dolt_branch('right');",
            "SELECT dolt_checkout('right');",
            "ALTER TABLE t ADD COLUMN c int;",
            "DELETE FROM t WHERE ctid = (SELECT min(ctid) FROM t);",
            "SELECT dolt_commit('-Am', 'right');",
            "SELECT dolt_checkout('main');",
            "INSERT INTO t VALUES (1, 1);",
            "SELECT dolt_commit('-Am', 'main');",
            "SET dolt_allow_commit_conflicts = 1;",
            "SELECT * FROM dolt_merge('right');",
        ],
        assertions: &[
            ScriptTestAssertion {
                query: "SELECT base_a, base_b, our_a, our_b, their_a, their_c, dolt_base_cardinality, dolt_our_cardinality, dolt_their_cardinality FROM dolt_conflicts_t;",
                expected: Expected::Rows {
                    columns: &[Column("base_a", INT4), Column("base_b", INT4), Column("our_a", INT4), Column("our_b", INT4), Column("their_a", INT4), Column("their_c", INT4), Column("dolt_base_cardinality", INT8), Column("dolt_our_cardinality", INT8), Column("dolt_their_cardinality", INT8)],
                    rows: &[
                        &[T("1"), T("1"), T("1"), T("1"), T("1"), Null, T("2"), T("3"), T("1")],
                    ],
                    tag: "SELECT 1",
                },
                ..A
            },
            ScriptTestAssertion {
                query: "SELECT dolt_conflicts_resolve('--theirs', 't');",
                expected: Expected::Rows {
                    columns: &[Column("dolt_conflicts_resolve", INT8)],
                    rows: &[&[T("0")]],
                    tag: "SELECT 1",
                },
                ..A
            },
            ScriptTestAssertion {
                query: "SELECT a, b, c FROM t;",
                expected: Expected::Rows {
                    columns: &[Column("a", INT4), Column("b", INT4), Column("c", INT4)],
                    rows: &[&[T("1"), T("1"), Null]],
                    tag: "SELECT 1",
                },
                ..A
            },
        ],
        ..S
    }]);
}

#[test]
fn test_merges_keep_another_merge_s_conflicts() {
    run_scripts(&[
        ScriptTest {
            name: "a merge into a table holding another merge's conflicts of the same columns keeps both merges' conflicts",
            intent: "Each merge's conflicts keep their own base and their commit, and --theirs takes each one's row.",
            set_up_script: &[
                "CREATE TABLE t (pk int PRIMARY KEY, c int);",
                "INSERT INTO t VALUES (1, 1), (2, 2);",
                "SELECT dolt_commit('-Am', 'base');",
                "SELECT dolt_branch('other');",
                "SELECT dolt_branch('other2');",
                "UPDATE t SET c = 10 WHERE pk = 1;",
                "UPDATE t SET c = 20 WHERE pk = 2;",
                "SELECT dolt_commit('-am', 'main');",
                "SELECT dolt_checkout('other');",
                "UPDATE t SET c = -10 WHERE pk = 1;",
                "SELECT dolt_commit('-am', 'other');",
                "SELECT dolt_checkout('other2');",
                "UPDATE t SET c = -20 WHERE pk = 2;",
                "SELECT dolt_commit('-am', 'other2');",
                "SELECT dolt_checkout('main');",
                "SET dolt_allow_commit_conflicts = 1;",
                "SELECT * FROM dolt_merge('other');",
                "SELECT dolt_commit('-afm', 'commit conflicts on main');",
            ],
            assertions: &[
                ScriptTestAssertion {
                    query: "SELECT fast_forward, conflicts, message FROM dolt_merge('other2');",
                    expected: Expected::Rows {
                        columns: &[Column("fast_forward", INT8), Column("conflicts", INT8), Column("message", TEXT)],
                        rows: &[&[T("0"), T("1"), T("conflicts found")]],
                        tag: "SELECT 1",
                    },
                    notices: &[Diagnostic { severity: "WARNING", code: "01000", message: "merge has unresolved conflicts or constraint violations", ..N }],
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT base_pk, our_c, their_c FROM dolt_conflicts_t ORDER BY base_pk;",
                    expected: Expected::Rows {
                        columns: &[Column("base_pk", INT4), Column("our_c", INT4), Column("their_c", INT4)],
                        rows: &[&[T("1"), T("10"), T("-10")], &[T("2"), T("20"), T("-20")]],
                        tag: "SELECT 2",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT dolt_conflicts_resolve('--theirs', 't');",
                    expected: Expected::Ok,
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT pk, c FROM t ORDER BY pk;",
                    expected: Expected::Rows {
                        columns: &[Column("pk", INT4), Column("c", INT4)],
                        rows: &[&[T("1"), T("-10")], &[T("2"), T("-20")]],
                        tag: "SELECT 2",
                    },
                    ..A
                },
            ],
            ..S
        },
        ScriptTest {
            name: "a row two merges conflicted on, with different columns, in a table's conflicts",
            intent: "The conflicts view shows the union of the merges' columns, each conflict filling its own merge's, and --theirs takes the rows in their commits' hash order, the last winning.",
            set_up_script: &[
                "CREATE TABLE t (pk int PRIMARY KEY, col1 int);",
                "INSERT INTO t VALUES (1, 1);",
                "SELECT dolt_commit('-Am', 'base');",
                "SELECT dolt_branch('other');",
                "UPDATE t SET col1 = 100 WHERE pk = 1;",
                "SELECT dolt_commit('-am', 'left edit');",
                "SELECT dolt_checkout('other');",
                "UPDATE t SET col1 = -100 WHERE pk = 1;",
                "SELECT dolt_commit('-am', 'right edit');",
                "SELECT dolt_checkout('main');",
                "SET dolt_allow_commit_conflicts = 1;",
                "SELECT * FROM dolt_merge('other');",
                "SELECT dolt_commit('-afm', 'commit conflicts on main');",
                "ALTER TABLE t ADD COLUMN col2 int;",
                "SELECT dolt_commit('-afm', 'alter schema');",
                "SELECT dolt_checkout('-b', 'other2');",
                "UPDATE t SET col2 = -1000 WHERE pk = 1;",
                "SELECT dolt_commit('-afm', 'update pk 1 to -1000');",
                "SELECT dolt_checkout('main');",
                "UPDATE t SET col2 = 1000 WHERE pk = 1;",
                "SELECT dolt_commit('-afm', 'update pk 1 to 1000');",
                "SELECT * FROM dolt_merge('other2');",
            ],
            assertions: &[
                ScriptTestAssertion {
                    query: "SELECT base_col1, base_col2, our_col1, our_col2, their_col1, their_col2 FROM dolt_conflicts_t ORDER BY their_col2 NULLS FIRST;",
                    expected: Expected::Rows {
                        columns: &[
                            Column("base_col1", INT4),
                            Column("base_col2", INT4),
                            Column("our_col1", INT4),
                            Column("our_col2", INT4),
                            Column("their_col1", INT4),
                            Column("their_col2", INT4),
                        ],
                        rows: &[
                            &[T("1"), Null, T("100"), T("1000"), T("-100"), Null],
                            &[T("100"), Null, T("100"), T("1000"), T("100"), T("-1000")],
                        ],
                        tag: "SELECT 2",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT set_config('test.last', (SELECT concat_ws(',', their_col1, their_col2) FROM dolt_conflicts_t ORDER BY dolt_from_root_ish DESC LIMIT 1), FALSE) IS NOT NULL;",
                    expected: Expected::Rows { columns: &[Column("?column?", BOOL)], rows: &[&[T("t")]], tag: "SELECT 1" },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT dolt_conflicts_resolve('--theirs', 't');",
                    expected: Expected::Ok,
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT concat_ws(',', col1, col2) = current_setting('test.last') FROM t;",
                    expected: Expected::Rows { columns: &[Column("?column?", BOOL)], rows: &[&[T("t")]], tag: "SELECT 1" },
                    ..A
                },
            ],
            ..S
        },
    ]);
}

#[test]
fn test_diffs_pair_rows_across_primary_key_changes() {
    run_scripts(&[ScriptTest {
        name: "dolt_diff(), dolt_blame_<t>, and their pairing across primary key changes",
        intent: "Rows pair by a key both versions hold: rows sharing a key value of the new key pair nothing, a key moved to a column both versions have pairs by it, and a key column's type change pairs through the cast.",
        set_up_script: &[
            "CREATE TABLE d (a int, b int, c text, PRIMARY KEY (a, b));",
            "INSERT INTO d VALUES (1, 1, 'x'), (1, 2, 'y'), (2, 1, 'z');",
            "CREATE TABLE n (a int PRIMARY KEY, c int);",
            "INSERT INTO n VALUES (1, 10), (2, 20);",
            "CREATE TABLE w (a int PRIMARY KEY, b text);",
            "INSERT INTO w VALUES (1, 'one'), (2, 'two');",
            "SELECT dolt_commit('-Am', 'one');",
            "ALTER TABLE d DROP CONSTRAINT d_pkey;",
            "DELETE FROM d WHERE b = 2;",
            "ALTER TABLE d ADD PRIMARY KEY (a);",
            "ALTER TABLE n DROP CONSTRAINT n_pkey;",
            "ALTER TABLE n DROP COLUMN a;",
            "ALTER TABLE n ADD PRIMARY KEY (c);",
            "ALTER TABLE w ALTER COLUMN a TYPE bigint;",
            "UPDATE w SET b = 'TWO' WHERE a = 2;",
            "SELECT dolt_commit('-am', 'two');",
        ],
        assertions: &[
            ScriptTestAssertion {
                query: "SELECT to_a, to_b, to_c, from_a, from_b, from_c, dolt_diff_type FROM dolt_diff('HEAD~', 'HEAD', 'd') ORDER BY to_a, from_a, from_b;",
                    expected: Expected::Rows {
                        columns: &[Column("to_a", INT4), Column("to_b", INT4), Column("to_c", TEXT), Column("from_a", INT4), Column("from_b", INT4), Column("from_c", TEXT), Column("dolt_diff_type", TEXT)],
                        rows: &[
                        &[T("1"), T("1"), T("x"), Null, Null, Null, T("added")],
                        &[Null, Null, Null, T("1"), T("1"), T("x"), T("removed")],
                        &[Null, Null, Null, T("1"), T("2"), T("y"), T("removed")],
                        ],
                        tag: "SELECT 3",
                    },
                ..A
            },
            ScriptTestAssertion {
                query: "SELECT to_c, from_c, dolt_diff_type FROM dolt_diff('HEAD~', 'HEAD', 'n') ORDER BY to_c, from_c;",
                    expected: Expected::Rows {
                        columns: &[Column("to_c", INT4), Column("from_c", INT4), Column("dolt_diff_type", TEXT)],
                        rows: &[
                        &[T("10"), T("10"), T("modified")],
                        &[T("20"), T("20"), T("modified")],
                        ],
                        tag: "SELECT 2",
                    },
                ..A
            },
            ScriptTestAssertion {
                query: "SELECT to_a, to_b, from_a, from_b, dolt_diff_type FROM dolt_diff('HEAD~', 'HEAD', 'w') ORDER BY to_a, from_a;",
                    expected: Expected::Rows {
                        columns: &[Column("to_a", INT8), Column("to_b", TEXT), Column("from_a", INT4), Column("from_b", TEXT), Column("dolt_diff_type", TEXT)],
                        rows: &[
                        &[T("1"), T("one"), T("1"), T("one"), T("modified")],
                        &[T("2"), T("TWO"), T("2"), T("two"), T("modified")],
                        ],
                        tag: "SELECT 2",
                    },
                ..A
            },
            ScriptTestAssertion {
                query: "SELECT a, dolt_message FROM dolt_blame_d ORDER BY a;",
                    expected: Expected::Rows {
                        columns: &[Column("a", INT4), Column("dolt_message", TEXT)],
                        rows: &[
                        &[T("1"), T("two")],
                        &[T("2"), T("one")],
                        ],
                        tag: "SELECT 2",
                    },
                ..A
            },
        ],
        ..S
    }, ScriptTest {
        name: "dolt_patch across primary key changes replays onto the first revision",
        intent: "A patch across a key change deletes the rows it changes by the old key, or by all values for a table without one, before the definition changes, and inserts the new rows after them.",
        set_up_script: &[
            "CREATE TABLE t (a int, b int, c text, PRIMARY KEY (a, b));",
            "INSERT INTO t VALUES (1, 1, 'x'), (1, 2, 'y'), (2, 1, 'z'), (3, 1, NULL);",
            "CREATE TABLE k (a int, b int);",
            "INSERT INTO k VALUES (1, 1), (1, 1), (2, 2);",
            "SELECT dolt_commit('-Am', 'before');",
            "SELECT dolt_branch('old');",
            "ALTER TABLE t DROP CONSTRAINT t_pkey;",
            "DELETE FROM t WHERE (a, b) = (1, 2);",
            "UPDATE t SET c = 'zz' WHERE a = 2;",
            "ALTER TABLE t ADD PRIMARY KEY (a);",
            "DELETE FROM k WHERE ctid = (SELECT min(ctid) FROM k WHERE a = 1);",
            "ALTER TABLE k ADD COLUMN id int NOT NULL DEFAULT 0;",
            "UPDATE k SET id = a * 10 + b;",
            "ALTER TABLE k ADD PRIMARY KEY (id);",
            "SELECT dolt_commit('-am', 'after');",
            "CREATE TEMP TABLE stmts AS SELECT statement_order, statement FROM dolt_patch('HEAD~', 'HEAD');",
            "SELECT dolt_checkout('old');",
            "DO $$ DECLARE s record; BEGIN FOR s IN SELECT statement FROM stmts ORDER BY statement_order LOOP EXECUTE s.statement; END LOOP; END $$;",
            "SELECT dolt_add('.');",
        ],
        assertions: &[
            ScriptTestAssertion {
                query: "SELECT count(*) FROM stmts WHERE statement LIKE 'DELETE%';",
                    expected: Expected::Rows {
                        columns: &[Column("count", INT8)],
                        rows: &[
                        &[T("5")],
                        ],
                        tag: "SELECT 1",
                    },
                ..A
            },
            ScriptTestAssertion {
                query: "SELECT * FROM t ORDER BY a;",
                    expected: Expected::Rows {
                        columns: &[Column("a", INT4), Column("b", INT4), Column("c", TEXT)],
                        rows: &[
                        &[T("1"), T("1"), T("x")],
                        &[T("2"), T("1"), T("zz")],
                        &[T("3"), T("1"), Null],
                        ],
                        tag: "SELECT 3",
                    },
                ..A
            },
            ScriptTestAssertion {
                query: "SELECT a, b, id FROM k ORDER BY id;",
                    expected: Expected::Rows {
                        columns: &[Column("a", INT4), Column("b", INT4), Column("id", INT4)],
                        rows: &[
                        &[T("1"), T("1"), T("11")],
                        &[T("2"), T("2"), T("22")],
                        ],
                        tag: "SELECT 2",
                    },
                ..A
            },
            ScriptTestAssertion {
                query: "SELECT to_table_name, data_change, schema_change FROM dolt_diff_summary('main', 'STAGED');",
                    expected: Expected::Rows {
                        columns: &[Column("to_table_name", TEXT), Column("data_change", BOOL), Column("schema_change", BOOL)],
                        rows: &[
                        ],
                        tag: "SELECT 0",
                    },
                ..A
            },
        ],
        ..S
    }]);
}

#[test]
fn test_dolt_conflicts_resolve_clears_every_schema_conflict_it_resolves() {
    const SET_UP: &[&str] = &[
        "CREATE TABLE t (pk int PRIMARY KEY, c0 int);",
        "CREATE TABLE u (pk int PRIMARY KEY, c0 int);",
        "INSERT INTO t VALUES (1, 1);",
        "INSERT INTO u VALUES (1, 1);",
        "SELECT dolt_commit('-Am', 'base');",
        "SELECT dolt_branch('other');",
        "ALTER TABLE t ALTER COLUMN c0 TYPE varchar(20);",
        "ALTER TABLE u ALTER COLUMN c0 TYPE varchar(20);",
        "SELECT dolt_commit('-am', 'main');",
        "SELECT dolt_checkout('other');",
        "ALTER TABLE t ALTER COLUMN c0 TYPE timestamp(6) USING NULL;",
        "ALTER TABLE u ALTER COLUMN c0 TYPE timestamp(6) USING NULL;",
        "SELECT dolt_commit('-am', 'other');",
        "SELECT dolt_checkout('main');",
        "SET dolt_allow_commit_conflicts = 1;",
    ];
    const MERGE: ScriptTestAssertion = ScriptTestAssertion {
        query: "SELECT fast_forward, conflicts, message FROM dolt_merge('other');",
        expected: Expected::Rows {
            columns: &[Column("fast_forward", INT8), Column("conflicts", INT8), Column("message", TEXT)],
            rows: &[&[T("0"), T("1"), T("conflicts found")]],
            tag: "SELECT 1",
        },
        notices: &[Diagnostic { severity: "WARNING", code: "01000", message: "merge has unresolved conflicts or constraint violations", ..N }],
        ..A
    };
    const NO_SCHEMA_CONFLICTS: ScriptTestAssertion = ScriptTestAssertion {
        query: "SELECT table_name FROM dolt_schema_conflicts;",
        expected: Expected::Rows { columns: &[Column("table_name", TEXT)], rows: &[], tag: "SELECT 0" },
        ..A
    };
    const UNSTAGED: ScriptTestAssertion = ScriptTestAssertion {
        query: "SELECT * FROM dolt_status ORDER BY table_name;",
        expected: Expected::Rows {
            columns: &[Column("table_name", TEXT), Column("staged", BOOL), Column("status", TEXT)],
            rows: &[
                &[T("public.t"), T("t"), T("merged")],
                &[T("public.t"), T("f"), T("modified")],
                &[T("public.u"), T("t"), T("merged")],
                &[T("public.u"), T("f"), T("modified")],
            ],
            tag: "SELECT 4",
        },
        ..A
    };
    const TYPES: &str = "SELECT attrelid::regclass::text, format_type(atttypid, atttypmod) FROM pg_attribute WHERE attrelid IN ('t'::regclass, 'u'::regclass) AND attname = 'c0' ORDER BY 1;";
    run_scripts(&[
        ScriptTest {
            name: "dolt_conflicts_resolve('--theirs', '.') of two tables' schema conflicts",
            intent: "Resolving every schema conflict in one call takes their definitions, clears each conflict, and shows the tables as merged, with their changes unstaged, until a commit.",
            set_up_script: SET_UP,
            assertions: &[
                MERGE,
                ScriptTestAssertion {
                    query: "SELECT table_name FROM dolt_schema_conflicts ORDER BY table_name;",
                    expected: Expected::Rows {
                        columns: &[Column("table_name", TEXT)],
                        rows: &[&[T("public.t")], &[T("public.u")]],
                        tag: "SELECT 2",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT dolt_conflicts_resolve('--theirs', '.');",
                    expected: Expected::Rows { columns: &[Column("dolt_conflicts_resolve", INT8)], rows: &[&[T("0")]], tag: "SELECT 1" },
                    ..A
                },
                NO_SCHEMA_CONFLICTS,
                UNSTAGED,
                ScriptTestAssertion {
                    query: TYPES,
                    expected: Expected::Rows {
                        columns: &[Column("attrelid", TEXT), Column("format_type", TEXT)],
                        rows: &[&[T("t"), T("timestamp(6) without time zone")], &[T("u"), T("timestamp(6) without time zone")]],
                        tag: "SELECT 2",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT dolt_commit('-Am', 'merged');",
                    expected: Expected::Ok,
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT * FROM dolt_status;",
                    expected: Expected::Rows {
                        columns: &[Column("table_name", TEXT), Column("staged", BOOL), Column("status", TEXT)],
                        rows: &[],
                        tag: "SELECT 0",
                    },
                    ..A
                },
            ],
            ..S
        },
        ScriptTest {
            name: "dolt_conflicts_resolve('--ours', 't', 'u') of two tables' schema conflicts",
            intent: "Resolving two named tables' schema conflicts with ours keeps our definitions and clears both conflicts.",
            set_up_script: SET_UP,
            assertions: &[
                MERGE,
                ScriptTestAssertion {
                    query: "SELECT dolt_conflicts_resolve('--ours', 't', 'u');",
                    expected: Expected::Rows { columns: &[Column("dolt_conflicts_resolve", INT8)], rows: &[&[T("0")]], tag: "SELECT 1" },
                    ..A
                },
                NO_SCHEMA_CONFLICTS,
                ScriptTestAssertion {
                    query: TYPES,
                    expected: Expected::Rows {
                        columns: &[Column("attrelid", TEXT), Column("format_type", TEXT)],
                        rows: &[&[T("t"), T("character varying(20)")], &[T("u"), T("character varying(20)")]],
                        tag: "SELECT 2",
                    },
                    ..A
                },
            ],
            ..S
        },
    ]);
}

