#[test]
fn test_merges_across_primary_key_changes() {
    run_scripts(&[
        ScriptTest {
            name: "a merge where one side changes the primary key and the other edits rows",
            intent: "The merge takes the changed key, converts the other side's rows to it, and records a conflict on a row both sides changed with every side's values.",
            set_up_script: &[
                "CREATE TABLE t (a int PRIMARY KEY, b int, c text);",
                "INSERT INTO t VALUES (1, 10, 'x'), (2, 20, 'y'), (3, 30, 'z');",
                "SELECT dolt_commit('-Am', 'one');",
                "SELECT dolt_branch('other');",
                "ALTER TABLE t DROP CONSTRAINT t_pkey;",
                "ALTER TABLE t ADD PRIMARY KEY (b);",
                "UPDATE t SET c = 'm' WHERE a = 1;",
                "SELECT dolt_commit('-am', 'rekey');",
                "SELECT dolt_checkout('other');",
                "UPDATE t SET c = 'Y' WHERE a = 2;",
                "UPDATE t SET c = 'o' WHERE a = 1;",
                "DELETE FROM t WHERE a = 3;",
                "INSERT INTO t VALUES (4, 40, 'w');",
                "SELECT dolt_commit('-am', 'edit');",
                "SELECT dolt_checkout('main');",
                "SET dolt_allow_commit_conflicts = 1;",
            ],
            assertions: &[
                ScriptTestAssertion {
                    query: "SELECT fast_forward, conflicts, message FROM dolt_merge('other');",
                    expected: Expected::Rows {
                        columns: &[Column("fast_forward", INT8), Column("conflicts", INT8), Column("message", TEXT)],
                        rows: &[&[T("0"), T("1"), T("conflicts found")]],
                        tag: "SELECT 1",
                    },
                    notices: &[Diagnostic { severity: "WARNING", code: "01000", message: "merge has unresolved conflicts or constraint violations", ..N }],
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT * FROM t ORDER BY b;",
                    expected: Expected::Rows {
                        columns: &[Column("a", INT4), Column("b", INT4), Column("c", TEXT)],
                        rows: &[
                            &[T("1"), T("10"), T("m")],
                            &[T("2"), T("20"), T("Y")],
                            &[T("4"), T("40"), T("w")],
                        ],
                        tag: "SELECT 3",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT pg_get_constraintdef(oid) FROM pg_constraint WHERE conrelid = 't'::regclass AND contype = 'p';",
                    expected: Expected::Rows {
                        columns: &[Column("pg_get_constraintdef", TEXT)],
                        rows: &[&[T("PRIMARY KEY (b)")]],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT base_a, base_b, base_c, our_a, our_b, our_c, dolt_our_diff_type, their_a, their_b, their_c, dolt_their_diff_type FROM dolt_conflicts_t;",
                    expected: Expected::Rows {
                        columns: &[
                            Column("base_a", INT4),
                            Column("base_b", INT4),
                            Column("base_c", TEXT),
                            Column("our_a", INT4),
                            Column("our_b", INT4),
                            Column("our_c", TEXT),
                            Column("dolt_our_diff_type", TEXT),
                            Column("their_a", INT4),
                            Column("their_b", INT4),
                            Column("their_c", TEXT),
                            Column("dolt_their_diff_type", TEXT),
                        ],
                        rows: &[&[T("1"), T("10"), T("x"), T("1"), T("10"), T("m"), T("modified"), T("1"), T("10"), T("o"), T("modified")]],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT dolt_conflicts_resolve('--theirs', 't');",
                    expected: Expected::Ok,
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT * FROM t ORDER BY b;",
                    expected: Expected::Rows {
                        columns: &[Column("a", INT4), Column("b", INT4), Column("c", TEXT)],
                        rows: &[
                            &[T("1"), T("10"), T("o")],
                            &[T("2"), T("20"), T("Y")],
                            &[T("4"), T("40"), T("w")],
                        ],
                        tag: "SELECT 3",
                    },
                    ..A
                },
            ],
            ..S
        },
        ScriptTest {
            name: "a merge whose converted rows share a key of the changed primary key",
            intent: "Two rows that become one key fail the merge as Postgres' ADD PRIMARY KEY fails over duplicates, and the branch is left as it was.",
            set_up_script: &[
                "CREATE TABLE t (a int PRIMARY KEY, b int);",
                "INSERT INTO t VALUES (1, 1), (2, 2);",
                "SELECT dolt_commit('-Am', 'one');",
                "SELECT dolt_branch('other');",
                "ALTER TABLE t DROP CONSTRAINT t_pkey;",
                "ALTER TABLE t ADD PRIMARY KEY (b);",
                "SELECT dolt_commit('-am', 'rekey');",
                "SELECT dolt_checkout('other');",
                "UPDATE t SET b = 1 WHERE a = 2;",
                "SELECT dolt_commit('-am', 'duplicate');",
                "SELECT dolt_checkout('main');",
            ],
            assertions: &[
                ScriptTestAssertion {
                    query: "SELECT * FROM dolt_merge('other');",
                    expected: Expected::Error(Diagnostic { code: "23505", message: "could not create unique index \"t_pkey\"", detail: "Key (b)=(1) is duplicated.", ..E }),
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT * FROM t ORDER BY a;",
                    expected: Expected::Rows {
                        columns: &[Column("a", INT4), Column("b", INT4)],
                        rows: &[&[T("1"), T("1")], &[T("2"), T("2")]],
                        tag: "SELECT 2",
                    },
                    ..A
                },
            ],
            ..S
        },
        ScriptTest {
            name: "a merge whose converted rows hold NULL in a column of the changed primary key",
            intent: "A NULL in a new key column fails the merge as Postgres' ADD PRIMARY KEY fails over it.",
            set_up_script: &[
                "CREATE TABLE t (a int PRIMARY KEY, b int);",
                "INSERT INTO t VALUES (1, 1);",
                "SELECT dolt_commit('-Am', 'one');",
                "SELECT dolt_branch('other');",
                "ALTER TABLE t DROP CONSTRAINT t_pkey;",
                "ALTER TABLE t ADD PRIMARY KEY (b);",
                "SELECT dolt_commit('-am', 'rekey');",
                "SELECT dolt_checkout('other');",
                "INSERT INTO t VALUES (2, NULL);",
                "SELECT dolt_commit('-am', 'null');",
                "SELECT dolt_checkout('main');",
            ],
            assertions: &[
                ScriptTestAssertion {
                    query: "SELECT * FROM dolt_merge('other');",
                    expected: Expected::Error(Diagnostic { code: "23502", message: "column \"b\" of relation \"t\" contains null values", ..E }),
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT * FROM dolt_status;",
                    expected: Expected::Rows {
                        columns: &[Column("table_name", TEXT), Column("staged", BOOL), Column("status", TEXT)],
                        rows: &[],
                        tag: "SELECT 0",
                    },
                    ..A
                },
            ],
            ..S
        },
    ]);
}

#[test]
fn test_merges_of_tables_and_columns_both_branches_added() {
    run_scripts(&[
        ScriptTest {
            name: "a merge of tables of one name both branches added",
            intent: "Tables of one name both branches added merge as one table against an empty base: their columns merge as any schema merge merges them, rows of one key conflict, and the conflicts show the base's columns as ours with no values.",
            set_up_script: &[
                "SELECT dolt_checkout('-b', 'other');",
                "CREATE TABLE t (pk int PRIMARY KEY, col1 int, extracol int);",
                "INSERT INTO t VALUES (1, 1, 1), (3, 3, 3);",
                "SELECT dolt_commit('-Am', 'right');",
                "SELECT dolt_checkout('main');",
                "CREATE TABLE t (pk int PRIMARY KEY, col1 int);",
                "INSERT INTO t VALUES (2, 2), (3, 30);",
                "SELECT dolt_commit('-Am', 'left');",
                "SET dolt_allow_commit_conflicts = 1;",
            ],
            assertions: &[
                ScriptTestAssertion {
                    query: "SELECT fast_forward, conflicts, message FROM dolt_merge('other');",
                    expected: Expected::Rows {
                        columns: &[Column("fast_forward", INT8), Column("conflicts", INT8), Column("message", TEXT)],
                        rows: &[&[T("0"), T("1"), T("conflicts found")]],
                        tag: "SELECT 1",
                    },
                    notices: &[Diagnostic { severity: "WARNING", code: "01000", message: "merge has unresolved conflicts or constraint violations", ..N }],
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT * FROM t ORDER BY pk;",
                    expected: Expected::Rows {
                        columns: &[Column("pk", INT4), Column("col1", INT4), Column("extracol", INT4)],
                        rows: &[&[T("1"), T("1"), T("1")], &[T("2"), T("2"), Null], &[T("3"), T("30"), Null]],
                        tag: "SELECT 3",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT base_pk, base_col1, base_extracol, our_pk, our_col1, our_extracol, dolt_our_diff_type, their_pk, their_col1, their_extracol, dolt_their_diff_type FROM dolt_conflicts_t;",
                    expected: Expected::Rows {
                        columns: &[
                            Column("base_pk", INT4),
                            Column("base_col1", INT4),
                            Column("base_extracol", INT4),
                            Column("our_pk", INT4),
                            Column("our_col1", INT4),
                            Column("our_extracol", INT4),
                            Column("dolt_our_diff_type", TEXT),
                            Column("their_pk", INT4),
                            Column("their_col1", INT4),
                            Column("their_extracol", INT4),
                            Column("dolt_their_diff_type", TEXT),
                        ],
                        rows: &[&[Null, Null, Null, T("3"), T("30"), Null, T("added"), T("3"), T("3"), T("3"), T("added")]],
                        tag: "SELECT 1",
                    },
                    ..A
                },
            ],
            ..S
        },
        ScriptTest {
            name: "a merge of columns of one name both branches added with types of different categories",
            intent: "Two columns of one name whose types differ in category are different columns, which a merge can't both keep, a schema conflict with Dolt's description.",
            set_up_script: &[
                "CREATE TABLE y (pk int PRIMARY KEY);",
                "INSERT INTO y VALUES (1);",
                "SELECT dolt_commit('-Am', 'base');",
                "SELECT dolt_checkout('-b', 'other');",
                "ALTER TABLE y ADD COLUMN c text;",
                "SELECT dolt_commit('-Am', 'right');",
                "SELECT dolt_checkout('main');",
                "ALTER TABLE y ADD COLUMN c int;",
                "SELECT dolt_commit('-Am', 'left');",
                "SET dolt_allow_commit_conflicts = 1;",
            ],
            assertions: &[
                ScriptTestAssertion {
                    query: "SELECT fast_forward, conflicts, message FROM dolt_merge('other');",
                    expected: Expected::Rows {
                        columns: &[Column("fast_forward", INT8), Column("conflicts", INT8), Column("message", TEXT)],
                        rows: &[&[T("0"), T("1"), T("conflicts found")]],
                        tag: "SELECT 1",
                    },
                    notices: &[Diagnostic { severity: "WARNING", code: "01000", message: "merge has unresolved conflicts or constraint violations", ..N }],
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT table_name, description FROM dolt_schema_conflicts;",
                    expected: Expected::Rows {
                        columns: &[Column("table_name", TEXT), Column("description", TEXT)],
                        rows: &[&[T("public.y"), T("incompatible column types for column 'c': integer and text")]],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT attname FROM pg_attribute WHERE attrelid = 'y'::regclass AND attnum > 0 ORDER BY attnum;",
                    expected: Expected::Rows { columns: &[Column("attname", NAME)], rows: &[&[T("pk")], &[T("c")]], tag: "SELECT 2" },
                    ..A
                },
            ],
            ..S
        },
        ScriptTest {
            name: "a merge of columns of one name and definition both branches added under different ids",
            intent: "Columns one side added as int and changed to varchar and those the other side added as varchar are one column each, kept under the smaller id, so that either direction of the merge gives the same table.",
            set_up_script: &[
                "SELECT dolt_branch('branch1');",
                "CREATE TABLE t (pk int PRIMARY KEY, col1 int, col2 int);",
                "ALTER TABLE t ALTER COLUMN col1 TYPE varchar(255), ALTER COLUMN col2 TYPE varchar(255);",
                "INSERT INTO t VALUES (1, 'one', 'a'), (2, 'two', 'b');",
                "SELECT dolt_commit('-Am', 'main');",
                "SELECT dolt_checkout('branch1');",
                "CREATE TABLE t (pk int PRIMARY KEY, col1 varchar(255), col2 varchar(255));",
                "INSERT INTO t VALUES (3, 'three', 'c');",
                "SELECT dolt_commit('-Am', 'branch1');",
                "SELECT set_config('test.branch1', dolt_hashof('HEAD'), FALSE);",
            ],
            assertions: &[
                ScriptTestAssertion {
                    query: "SELECT fast_forward, conflicts, message FROM dolt_merge('main');",
                    expected: Expected::Rows {
                        columns: &[Column("fast_forward", INT8), Column("conflicts", INT8), Column("message", TEXT)],
                        rows: &[&[T("0"), T("0"), T("merge successful")]],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT set_config('test.merged', dolt_hashof_table('t'), FALSE) IS NOT NULL;",
                    expected: Expected::Rows { columns: &[Column("?column?", BOOL)], rows: &[&[T("t")]], tag: "SELECT 1" },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT dolt_reset('--hard', current_setting('test.branch1'));",
                    expected: Expected::Ok,
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT dolt_checkout('main');",
                    expected: Expected::Ok,
                    ..A
                },
                ScriptTestAssertion {
                    query: "PREPARE p AS SELECT pk, col1 FROM t ORDER BY pk;",
                    expected: Expected::Tag("PREPARE"),
                    ..A
                },
                ScriptTestAssertion {
                    query: "EXECUTE p;",
                    expected: Expected::Rows {
                        columns: &[Column("pk", INT4), Column("col1", VARCHAR)],
                        rows: &[&[T("1"), T("one")], &[T("2"), T("two")]],
                        tag: "SELECT 2",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT fast_forward, conflicts, message FROM dolt_merge('branch1');",
                    expected: Expected::Rows {
                        columns: &[Column("fast_forward", INT8), Column("conflicts", INT8), Column("message", TEXT)],
                        rows: &[&[T("0"), T("0"), T("merge successful")]],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "EXECUTE p;",
                    expected: Expected::Rows {
                        columns: &[Column("pk", INT4), Column("col1", VARCHAR)],
                        rows: &[&[T("1"), T("one")], &[T("2"), T("two")], &[T("3"), T("three")]],
                        tag: "SELECT 3",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT dolt_hashof_table('t') = current_setting('test.merged');",
                    expected: Expected::Rows { columns: &[Column("?column?", BOOL)], rows: &[&[T("t")]], tag: "SELECT 1" },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT * FROM t ORDER BY pk;",
                    expected: Expected::Rows {
                        columns: &[Column("pk", INT4), Column("col1", VARCHAR), Column("col2", VARCHAR)],
                        rows: &[&[T("1"), T("one"), T("a")], &[T("2"), T("two"), T("b")], &[T("3"), T("three"), T("c")]],
                        tag: "SELECT 3",
                    },
                    ..A
                },
            ],
            ..S
        },
    ]);
}

#[test]
fn test_identity_aliases_of_columns_follow_them_across_merges_and_renames() {
    const MERGED: ScriptTestAssertion = ScriptTestAssertion {
        query: "SELECT fast_forward, conflicts, message FROM dolt_merge('branch1');",
        expected: Expected::Rows {
            columns: &[Column("fast_forward", INT8), Column("conflicts", INT8), Column("message", TEXT)],
            rows: &[&[T("0"), T("0"), T("merge successful")]],
            tag: "SELECT 1",
        },
        ..A
    };
    run_scripts(&[
        ScriptTest {
            name: "a column both branches added under different ids, merged in either direction",
            intent: "The merge keeps the smaller id with an identity alias of the other in the root, so both directions give the same root, the column keeps its attribute number, and dolt_column_diff shows the column modified rather than dropped and added.",
            set_up_script: &[
                "SELECT dolt_branch('branch1');",
                "CREATE TABLE t (pk int PRIMARY KEY, col1 int);",
                "ALTER TABLE t ALTER COLUMN col1 TYPE varchar(255);",
                "INSERT INTO t VALUES (1, 'one'), (2, 'two');",
                "SELECT dolt_commit('-Am', 'main');",
                "SELECT dolt_checkout('branch1');",
                "CREATE TABLE t (pk int PRIMARY KEY, col1 varchar(255));",
                "INSERT INTO t VALUES (3, 'three');",
                "SELECT dolt_commit('-Am', 'branch1');",
                "SELECT set_config('test.branch1', dolt_hashof('HEAD'), FALSE);",
                "SELECT dolt_merge('main');",
                "SELECT set_config('test.merged', dolt_hashof_db(), FALSE);",
                "SELECT dolt_reset('--hard', current_setting('test.branch1'));",
                "SELECT dolt_checkout('main');",
            ],
            assertions: &[
                MERGED,
                ScriptTestAssertion {
                    query: "SELECT dolt_hashof_db() = current_setting('test.merged');",
                    expected: Expected::Rows { columns: &[Column("?column?", BOOL)], rows: &[&[T("t")]], tag: "SELECT 1" },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT attname, attnum FROM pg_attribute WHERE attrelid = 't'::regclass AND attnum > 0 ORDER BY attnum;",
                    expected: Expected::Rows {
                        columns: &[Column("attname", NAME), Column("attnum", INT2)],
                        rows: &[&[T("pk"), T("1")], &[T("col1"), T("2")]],
                        tag: "SELECT 2",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT table_name, column_name, diff_type FROM dolt_column_diff WHERE commit_hash = dolt_hashof('HEAD') ORDER BY 1, 2, 3;",
                    expected: Expected::Rows {
                        columns: &[Column("table_name", TEXT), Column("column_name", TEXT), Column("diff_type", TEXT)],
                        rows: &[&[T("public.t"), T("col1"), T("modified")], &[T("public.t"), T("pk"), T("modified")]],
                        tag: "SELECT 2",
                    },
                    ..A
                },
            ],
            ..S
        },
        ScriptTest {
            name: "a column renamed between two commits in dolt_history_<t> and dolt_diff_<t>",
            intent: "Columns pair by column id before name, so a renamed column shows its values from before the rename.",
            set_up_script: &[
                "CREATE TABLE r (pk int PRIMARY KEY, a int);",
                "INSERT INTO r VALUES (1, 10);",
                "SELECT dolt_commit('-Am', 'one');",
                "ALTER TABLE r RENAME COLUMN a TO b;",
                "UPDATE r SET b = 20;",
                "SELECT dolt_commit('-am', 'two');",
            ],
            assertions: &[
                ScriptTestAssertion {
                    query: "SELECT pk, b FROM dolt_history_r ORDER BY dolt_commit_date;",
                    expected: Expected::Rows {
                        columns: &[Column("pk", INT4), Column("b", INT4)],
                        rows: &[&[T("1"), T("10")], &[T("1"), T("20")]],
                        tag: "SELECT 2",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT from_pk, from_b, to_pk, to_b, dolt_diff_type FROM dolt_diff_r ORDER BY to_b;",
                    expected: Expected::Rows {
                        columns: &[
                            Column("from_pk", INT4),
                            Column("from_b", INT4),
                            Column("to_pk", INT4),
                            Column("to_b", INT4),
                            Column("dolt_diff_type", TEXT),
                        ],
                        rows: &[&[Null, Null, T("1"), T("10"), T("added")], &[T("1"), T("10"), T("1"), T("20"), T("modified")]],
                        tag: "SELECT 2",
                    },
                    ..A
                },
            ],
            ..S
        },
    ]);
}

#[test]
fn test_merges_and_checkouts_bring_tables_with_their_owned_sequences() {
    const NEXT: &str = "INSERT INTO t (v) VALUES (6) RETURNING id;";
    run_scripts(&[
        ScriptTest {
            name: "a merge brings in a table with a serial column",
            intent: "The merge installs the sequence the table's column owns with the table, so the column's default names it and continues from the merged branch's value.",
            set_up_script: &[
                "CREATE TABLE p (id int PRIMARY KEY);",
                "SELECT dolt_commit('-Am', 'base');",
                "SELECT dolt_branch('other');",
                "INSERT INTO p VALUES (1);",
                "SELECT dolt_commit('-Am', 'main');",
                "SELECT dolt_checkout('other');",
                "CREATE TABLE t (id serial PRIMARY KEY, v int);",
                "INSERT INTO t (v) VALUES (5);",
                "SELECT dolt_commit('-Am', 'other');",
                "SELECT dolt_checkout('main');",
            ],
            assertions: &[
                ScriptTestAssertion {
                    query: "SELECT fast_forward, conflicts, message FROM dolt_merge('other');",
                    expected: Expected::Rows {
                        columns: &[Column("fast_forward", INT8), Column("conflicts", INT8), Column("message", TEXT)],
                        rows: &[&[T("0"), T("0"), T("merge successful")]],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: NEXT,
                    expected: Expected::Rows { columns: &[Column("id", INT4)], rows: &[&[T("2")]], tag: "INSERT 0 1" },
                    ..A
                },
            ],
            ..S
        },
        ScriptTest {
            name: "a merge brings in a table with an identity column",
            intent: "The merge installs the identity column's sequence with the table.",
            set_up_script: &[
                "CREATE TABLE p (id int PRIMARY KEY);",
                "SELECT dolt_commit('-Am', 'base');",
                "SELECT dolt_branch('other');",
                "INSERT INTO p VALUES (1);",
                "SELECT dolt_commit('-Am', 'main');",
                "SELECT dolt_checkout('other');",
                "CREATE TABLE t (id int GENERATED ALWAYS AS IDENTITY PRIMARY KEY, v int);",
                "INSERT INTO t (v) VALUES (5);",
                "SELECT dolt_commit('-Am', 'other');",
                "SELECT dolt_checkout('main');",
                "SELECT dolt_merge('other');",
            ],
            assertions: &[ScriptTestAssertion {
                query: NEXT,
                expected: Expected::Rows { columns: &[Column("id", INT4)], rows: &[&[T("2")]], tag: "INSERT 0 1" },
                ..A
            }],
            ..S
        },
        ScriptTest {
            name: "dolt_checkout of a dropped table with a serial column",
            intent: "Checking the table out of HEAD brings its sequence back with it.",
            set_up_script: &[
                "CREATE TABLE t (id serial PRIMARY KEY, v int);",
                "INSERT INTO t (v) VALUES (5);",
                "SELECT dolt_commit('-Am', 't');",
                "DROP TABLE t;",
                "SELECT dolt_checkout('t');",
            ],
            assertions: &[ScriptTestAssertion {
                query: NEXT,
                expected: Expected::Rows { columns: &[Column("id", INT4)], rows: &[&[T("2")]], tag: "INSERT 0 1" },
                ..A
            }],
            ..S
        },
    ]);
}

#[test]
fn test_identity_aliases_of_objects_keep_one_object_across_merges() {
    const MERGED: ScriptTestAssertion = ScriptTestAssertion {
        query: "SELECT fast_forward, conflicts, message FROM dolt_merge('other');",
        expected: Expected::Rows {
            columns: &[Column("fast_forward", INT8), Column("conflicts", INT8), Column("message", TEXT)],
            rows: &[&[T("0"), T("0"), T("merge successful")]],
            tag: "SELECT 1",
        },
        ..A
    };
    const CONSTRAINTS: &str = "SELECT conname, contype::text FROM pg_constraint WHERE conrelid = 'def'::regclass ORDER BY 1;";
    run_scripts(&[
        ScriptTest {
            name: "a table one branch renamed to the name the other branch created it with, merged in either direction",
            intent: "Both branches' tables become one under the smaller id, with the smaller id's primary key and its name, so both merge directions give the same root and the branch keeps its table's OID.",
            set_up_script: &[
                "SELECT dolt_branch('other');",
                "CREATE TABLE abc (pk int PRIMARY KEY, v int);",
                "ALTER TABLE abc RENAME TO def;",
                "INSERT INTO def VALUES (1, 1);",
                "SELECT dolt_commit('-Am', 'main');",
                "SELECT set_config('test.oid', 'def'::regclass::oid::text, FALSE);",
                "SELECT dolt_checkout('other');",
                "CREATE TABLE def (pk int PRIMARY KEY, v int);",
                "INSERT INTO def VALUES (2, 2);",
                "SELECT dolt_commit('-Am', 'other');",
                "SELECT set_config('test.other', dolt_hashof('HEAD'), FALSE);",
                "SELECT dolt_merge('main');",
                "SELECT set_config('test.merged', dolt_hashof_db(), FALSE);",
                "SELECT dolt_reset('--hard', current_setting('test.other'));",
                "SELECT dolt_checkout('main');",
            ],
            assertions: &[
                MERGED,
                ScriptTestAssertion {
                    query: "SELECT dolt_hashof_db() = current_setting('test.merged'), 'def'::regclass::oid = current_setting('test.oid')::oid;",
                    expected: Expected::Rows {
                        columns: &[Column("?column?", BOOL), Column("?column?", BOOL)],
                        rows: &[&[T("t"), T("t")]],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT * FROM def ORDER BY pk;",
                    expected: Expected::Rows {
                        columns: &[Column("pk", INT4), Column("v", INT4)],
                        rows: &[&[T("1"), T("1")], &[T("2"), T("2")]],
                        tag: "SELECT 2",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: CONSTRAINTS,
                    expected: Expected::Rows {
                        columns: &[Column("conname", NAME), Column("contype", TEXT)],
                        rows: &[&[T("abc_pk_not_null"), T("n")], &[T("abc_pkey"), T("p")]],
                        tag: "SELECT 2",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "INSERT INTO def VALUES (2, 5);",
                    expected: Expected::Error(Diagnostic {
                        code: "23505",
                        message: "duplicate key value violates unique constraint \"abc_pkey\"",
                        detail: "Key (pk)=(2) already exists.",
                        schema: "public",
                        table: "def",
                        constraint: "abc_pkey",
                        ..E
                    }),
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT table_name, rows_added FROM dolt_diff_stat('HEAD~1', 'HEAD');",
                    expected: Expected::Rows {
                        columns: &[Column("table_name", TEXT), Column("rows_added", INT8)],
                        rows: &[&[T("public.def"), T("1")]],
                        tag: "SELECT 1",
                    },
                    ..A
                },
            ],
            ..S
        },
        ScriptTest {
            name: "a renamed table's serial sequence, foreign key, check, and index",
            intent: "The column's owned sequence and default, the foreign key and check of the table both branches added, and the index of one name each become one object, keeping the smaller id's name, and the sequence continues from the further of the two.",
            set_up_script: &[
                "CREATE TABLE p (id int PRIMARY KEY);",
                "INSERT INTO p VALUES (1), (2), (3);",
                "SELECT dolt_commit('-Am', 'base');",
                "SELECT dolt_branch('other');",
                "CREATE TABLE abc (pk serial PRIMARY KEY, v int REFERENCES p (id), w text CHECK (w <> 'z'));",
                "CREATE INDEX abc_w ON abc (w);",
                "ALTER TABLE abc RENAME TO def;",
                "ALTER INDEX abc_w RENAME TO def_w;",
                "INSERT INTO def (v, w) VALUES (1, 'a'), (2, 'b');",
                "SELECT dolt_commit('-Am', 'main');",
                "SELECT dolt_checkout('other');",
                "CREATE TABLE def (pk serial PRIMARY KEY, v int REFERENCES p (id), w text CHECK (w <> 'z'));",
                "CREATE INDEX def_w ON def (w);",
                "INSERT INTO def (pk, v, w) VALUES (10, 3, 'c');",
                "SELECT setval('def_pk_seq', 10);",
                "SELECT dolt_commit('-Am', 'other');",
                "SELECT dolt_checkout('main');",
            ],
            assertions: &[
                MERGED,
                ScriptTestAssertion {
                    query: CONSTRAINTS,
                    expected: Expected::Rows {
                        columns: &[Column("conname", NAME), Column("contype", TEXT)],
                        rows: &[
                            &[T("abc_pk_not_null"), T("n")],
                            &[T("abc_pkey"), T("p")],
                            &[T("abc_w_check"), T("c")],
                            &[T("def_v_fkey"), T("f")],
                        ],
                        tag: "SELECT 4",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT relname FROM pg_class WHERE relkind IN ('i', 'S') AND relnamespace = 'public'::regnamespace AND relname <> 'p_pkey' ORDER BY 1;",
                    expected: Expected::Rows {
                        columns: &[Column("relname", NAME)],
                        rows: &[&[T("abc_pkey")], &[T("def_pk_seq")], &[T("def_w")]],
                        tag: "SELECT 3",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "INSERT INTO def (v, w) VALUES (1, 'n') RETURNING pk;",
                    expected: Expected::Rows { columns: &[Column("pk", INT4)], rows: &[&[T("11")]], tag: "INSERT 0 1" },
                    ..A
                },
                ScriptTestAssertion {
                    query: "INSERT INTO def (v, w) VALUES (9, 'x');",
                    expected: Expected::Error(Diagnostic {
                        code: "23503",
                        message: "insert or update on table \"def\" violates foreign key constraint \"def_v_fkey\"",
                        detail: "Key (v)=(9) is not present in table \"p\".",
                        schema: "public",
                        table: "def",
                        constraint: "def_v_fkey",
                        ..E
                    }),
                    ..A
                },
            ],
            ..S
        },
        ScriptTest {
            name: "a row conflict in a table the merge keeps under the other branch's id",
            intent: "The conflicts view reads their side's row from their table under its own id, and resolving with theirs takes it.",
            set_up_script: &[
                "SET dolt_allow_commit_conflicts = 1;",
                "SELECT dolt_branch('main2');",
                "CREATE TABLE abc (pk int PRIMARY KEY, v int);",
                "ALTER TABLE abc RENAME TO def;",
                "INSERT INTO def VALUES (1, 1), (2, 2);",
                "SELECT dolt_commit('-Am', 'main');",
                "SELECT dolt_checkout('main2');",
                "CREATE TABLE def (pk int PRIMARY KEY, v int);",
                "INSERT INTO def VALUES (1, 100), (3, 3);",
                "SELECT dolt_commit('-Am', 'main2');",
                "SELECT dolt_merge('main');",
            ],
            assertions: &[
                ScriptTestAssertion {
                    query: "SELECT our_pk, our_v, their_pk, their_v FROM dolt_conflicts_def;",
                    expected: Expected::Rows {
                        columns: &[Column("our_pk", INT4), Column("our_v", INT4), Column("their_pk", INT4), Column("their_v", INT4)],
                        rows: &[&[T("1"), T("100"), T("1"), T("1")]],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT dolt_conflicts_resolve('--theirs', 'def');",
                    expected: Expected::Rows { columns: &[Column("dolt_conflicts_resolve", INT8)], rows: &[&[T("0")]], tag: "SELECT 1" },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT * FROM def ORDER BY pk;",
                    expected: Expected::Rows {
                        columns: &[Column("pk", INT4), Column("v", INT4)],
                        rows: &[&[T("1"), T("1")], &[T("2"), T("2")], &[T("3"), T("3")]],
                        tag: "SELECT 3",
                    },
                    ..A
                },
            ],
            ..S
        },
        ScriptTest {
            name: "uncommitted objects that name the table a merge moves to another id",
            intent: "A view and a foreign key the working state holds, which name the branch's table, name it under the id the merge keeps.",
            set_up_script: &[
                "SELECT dolt_branch('other');",
                "CREATE TABLE def (pk int PRIMARY KEY, v int);",
                "INSERT INTO def VALUES (2, 2);",
                "SELECT dolt_commit('-Am', 'main');",
                "SELECT dolt_checkout('other');",
                "CREATE TABLE abc (pk int PRIMARY KEY, v int);",
                "ALTER TABLE abc RENAME TO def;",
                "INSERT INTO def VALUES (1, 1);",
                "SELECT dolt_commit('-Am', 'other');",
                "CREATE VIEW vv AS SELECT pk, v FROM def;",
                "CREATE TABLE side (id int REFERENCES def (pk));",
                "INSERT INTO side VALUES (1);",
                "SELECT dolt_merge('main');",
            ],
            assertions: &[
                ScriptTestAssertion {
                    query: "SELECT * FROM vv ORDER BY pk;",
                    expected: Expected::Rows {
                        columns: &[Column("pk", INT4), Column("v", INT4)],
                        rows: &[&[T("1"), T("1")], &[T("2"), T("2")]],
                        tag: "SELECT 2",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "INSERT INTO side VALUES (5);",
                    expected: Expected::Error(Diagnostic {
                        code: "23503",
                        message: "insert or update on table \"side\" violates foreign key constraint \"side_id_fkey\"",
                        detail: "Key (id)=(5) is not present in table \"def\".",
                        schema: "public",
                        table: "side",
                        constraint: "side_id_fkey",
                        ..E
                    }),
                    ..A
                },
            ],
            ..S
        },
        ScriptTest {
            name: "indexes of one name and different definitions on a table both branches added",
            intent: "The index both branches added under one name with different columns is a schema conflict.",
            set_up_script: &[
                "SET dolt_allow_commit_conflicts = 1;",
                "SELECT dolt_branch('other');",
                "CREATE TABLE abc (pk int PRIMARY KEY, a int, b int);",
                "ALTER TABLE abc RENAME TO def;",
                "CREATE INDEX t_idx ON def (a);",
                "SELECT dolt_commit('-Am', 'main');",
                "SELECT dolt_checkout('other');",
                "CREATE TABLE def (pk int PRIMARY KEY, a int, b int);",
                "CREATE INDEX t_idx ON def (b);",
                "SELECT dolt_commit('-Am', 'other');",
                "SELECT dolt_merge('main');",
            ],
            assertions: &[ScriptTestAssertion {
                query: "SELECT table_name, description FROM dolt_schema_conflicts;",
                expected: Expected::Rows {
                    columns: &[Column("table_name", TEXT), Column("description", TEXT)],
                    rows: &[&[T("public.def"), T("two indexes with the name 't_idx' but different definitions")]],
                    tag: "SELECT 1",
                },
                ..A
            }],
            ..S
        },
    ]);
}

#[test]
fn test_merges_of_json_values_both_branches_changed() {
    run_scripts(&[ScriptTest {
        name: "merges of jsonb values both branches changed",
        intent: "A JSON object both branches changed merges key by key, nested objects included, while a key both changed differently, a key one deleted and the other changed, and arrays both changed conflict, as Dolt merges JSON.",
        set_up_script: &[
            "CREATE TABLE t (pk int PRIMARY KEY, j jsonb);",
            "INSERT INTO t VALUES (1, '{\"a\": {\"x\": 1, \"y\": 1}, \"k\": [1]}'), (2, '{\"k\": [1]}'), (3, '{\"a\": 1, \"b\": 1}'), (4, '{\"a\": 1}'), (5, '{\"a\": 1}'), (6, '[1]');",
            "SELECT dolt_commit('-Am', 'base');",
            "SELECT dolt_branch('right');",
            "UPDATE t SET j = '{\"a\": {\"x\": 2, \"y\": 1}, \"k\": [1]}' WHERE pk = 1;",
            "UPDATE t SET j = '{\"k\": [1, 2]}' WHERE pk = 2;",
            "UPDATE t SET j = '{\"b\": 1}' WHERE pk = 3;",
            "UPDATE t SET j = '{\"a\": 1, \"c\": 3}' WHERE pk = 4;",
            "UPDATE t SET j = '{\"a\": 2, \"b\": 1}' WHERE pk = 5;",
            "UPDATE t SET j = '[1, 2]' WHERE pk = 6;",
            "SELECT dolt_commit('-Am', 'left');",
            "SELECT dolt_checkout('right');",
            "UPDATE t SET j = '{\"a\": {\"x\": 1, \"y\": 2}, \"k\": [1]}' WHERE pk = 1;",
            "UPDATE t SET j = '{\"k\": [1, 3]}' WHERE pk = 2;",
            "UPDATE t SET j = '{\"a\": 2, \"b\": 1}' WHERE pk = 3;",
            "UPDATE t SET j = '{\"c\": 3}' WHERE pk = 4;",
            "UPDATE t SET j = '{\"a\": 3, \"b\": 1}' WHERE pk = 5;",
            "UPDATE t SET j = '[1, 3]' WHERE pk = 6;",
            "SELECT dolt_commit('-Am', 'right');",
            "SELECT dolt_checkout('main');",
            "BEGIN;",
        ],
        assertions: &[
            ScriptTestAssertion {
                query: "SELECT * FROM dolt_merge('right');",
                expected: Expected::Rows {
                    columns: &[Column("hash", TEXT), Column("fast_forward", INT8), Column("conflicts", INT8), Column("message", TEXT)],
                    rows: &[&[T(""), T("0"), T("1"), T("conflicts found")]],
                    tag: "SELECT 1",
                },
                notices: &[Diagnostic { severity: "WARNING", code: "01000", message: "merge has unresolved conflicts or constraint violations", ..N }],
                ..A
            },
            ScriptTestAssertion {
                query: "SELECT * FROM t ORDER BY pk;",
                expected: Expected::Rows {
                    columns: &[Column("pk", INT4), Column("j", JSONB)],
                    rows: &[
                        &[T("1"), T("{\"a\": {\"x\": 2, \"y\": 2}, \"k\": [1]}")],
                        &[T("2"), T("{\"k\": [1, 2]}")],
                        &[T("3"), T("{\"b\": 1}")],
                        &[T("4"), T("{\"c\": 3}")],
                        &[T("5"), T("{\"a\": 2, \"b\": 1}")],
                        &[T("6"), T("[1, 2]")],
                    ],
                    tag: "SELECT 6",
                },
                ..A
            },
            ScriptTestAssertion {
                query: "SELECT base_pk, our_j, their_j FROM dolt_conflicts_t ORDER BY base_pk;",
                expected: Expected::Rows {
                    columns: &[Column("base_pk", INT4), Column("our_j", JSONB), Column("their_j", JSONB)],
                    rows: &[
                        &[T("2"), T("{\"k\": [1, 2]}"), T("{\"k\": [1, 3]}")],
                        &[T("3"), T("{\"b\": 1}"), T("{\"a\": 2, \"b\": 1}")],
                        &[T("5"), T("{\"a\": 2, \"b\": 1}"), T("{\"a\": 3, \"b\": 1}")],
                        &[T("6"), T("[1, 2]"), T("[1, 3]")],
                    ],
                    tag: "SELECT 4",
                },
                ..A
            },
        ],
        ..S
    }]);
}

#[test]
fn test_workspace_writes_after_a_schema_change_and_a_failed_statement() {
    const STAGED: &str = "SELECT * FROM tbl AS OF 'STAGED' ORDER BY x;";
    run_scripts(&[
        ScriptTest {
            name: "dolt_workspace_<t> writes of a table whose columns changed since the staged root",
            intent: "Staging a row of a table whose columns changed stages the table's working definition with the staged rows converted by column id, and the row. Reverting and unstaging a row convert it to the other side's definition by column id, so the working set keeps its columns and the staged root the working definition it took.",
            set_up_script: &[
                "CREATE TABLE tbl (x int PRIMARY KEY, y int);",
                "INSERT INTO tbl VALUES (1, 1), (2, 2);",
                "SELECT dolt_commit('-Am', 'base');",
                "ALTER TABLE tbl ADD COLUMN w text;",
                "UPDATE tbl SET y = 10 WHERE x = 1;",
                "INSERT INTO tbl VALUES (3, 3, 'z');",
            ],
            assertions: &[
                ScriptTestAssertion {
                    query: "UPDATE dolt_workspace_tbl SET dolt_staged = TRUE WHERE to_x = 3;",
                    expected: Expected::Tag("UPDATE 1"),
                    ..A
                },
                ScriptTestAssertion {
                    query: STAGED,
                    expected: Expected::Rows {
                        columns: &[Column("x", INT4), Column("y", INT4), Column("w", TEXT)],
                        rows: &[&[T("1"), T("1"), Null], &[T("2"), T("2"), Null], &[T("3"), T("3"), T("z")]],
                        tag: "SELECT 3",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "DELETE FROM dolt_workspace_tbl WHERE to_x = 3 AND NOT dolt_staged;",
                    expected: Expected::Tag("DELETE 0"),
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT * FROM tbl ORDER BY x;",
                    expected: Expected::Rows {
                        columns: &[Column("x", INT4), Column("y", INT4), Column("w", TEXT)],
                        rows: &[&[T("1"), T("10"), Null], &[T("2"), T("2"), Null], &[T("3"), T("3"), T("z")]],
                        tag: "SELECT 3",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "UPDATE dolt_workspace_tbl SET dolt_staged = FALSE WHERE to_x = 3 AND dolt_staged;",
                    expected: Expected::Tag("UPDATE 1"),
                    ..A
                },
                ScriptTestAssertion {
                    query: STAGED,
                    expected: Expected::Rows {
                        columns: &[Column("x", INT4), Column("y", INT4), Column("w", TEXT)],
                        rows: &[&[T("1"), T("1"), Null], &[T("2"), T("2"), Null]],
                        tag: "SELECT 2",
                    },
                    ..A
                },
            ],
            ..S
        },
        ScriptTest {
            name: "dolt_workspace_<t> staging that fails, rolled back to a savepoint, then staging that succeeds",
            intent: "A statement whose staged rows fail the staged table's unique keys leaves nothing staged once its savepoint is rolled back, so the next statement stages only its own rows.",
            set_up_script: &[
                "CREATE TABLE t (id int PRIMARY KEY, u int);",
                "CREATE UNIQUE INDEX ix ON t (u);",
                "INSERT INTO t VALUES (5, 10);",
                "SELECT dolt_commit('-Am', 'base');",
                "DELETE FROM t WHERE id = 5;",
                "INSERT INTO t VALUES (1, 10), (2, 20);",
            ],
            assertions: &[
                ScriptTestAssertion { query: "BEGIN;", expected: Expected::Tag("BEGIN"), ..A },
                ScriptTestAssertion { query: "SAVEPOINT s;", expected: Expected::Tag("SAVEPOINT"), ..A },
                ScriptTestAssertion {
                    query: "UPDATE dolt_workspace_t SET dolt_staged = TRUE WHERE dolt_diff_type = 'added';",
                    expected: Expected::Error(Diagnostic {
                        code: "23505",
                        message: "duplicate key value violates unique constraint \"ix\"",
                        detail: "Key (u)=(10) already exists.",
                        schema: "public",
                        table: "t",
                        constraint: "ix",
                        ..E
                    }),
                    ..A
                },
                ScriptTestAssertion { query: "ROLLBACK TO s;", expected: Expected::Tag("ROLLBACK"), ..A },
                ScriptTestAssertion {
                    query: "UPDATE dolt_workspace_t SET dolt_staged = TRUE WHERE to_id = 2;",
                    expected: Expected::Tag("UPDATE 1"),
                    ..A
                },
                ScriptTestAssertion { query: "COMMIT;", expected: Expected::Tag("COMMIT"), ..A },
                ScriptTestAssertion {
                    query: "SELECT id, u FROM t AS OF 'STAGED' ORDER BY id;",
                    expected: Expected::Rows {
                        columns: &[Column("id", INT4), Column("u", INT4)],
                        rows: &[&[T("2"), T("20")], &[T("5"), T("10")]],
                        tag: "SELECT 2",
                    },
                    ..A
                },
            ],
            ..S
        },
        ScriptTest {
            name: "dolt_workspace_<t> staging checks unique indexes of expressions and with predicates",
            intent: "The staged rows' keys are formed as a write to the table forms them, so an index of an expression refuses two rows its expression makes equal and a partial index refuses only the rows its predicate covers.",
            set_up_script: &[
                "CREATE TABLE t (id int PRIMARY KEY, s text);",
                "CREATE UNIQUE INDEX ix ON t (lower(s));",
                "CREATE TABLE p (id int PRIMARY KEY, u int, active bool);",
                "CREATE UNIQUE INDEX px ON p (u) WHERE active;",
                "INSERT INTO t VALUES (1, 'A');",
                "INSERT INTO p VALUES (1, 10, true);",
                "SELECT dolt_commit('-Am', 'base');",
                "DELETE FROM t WHERE id = 1;",
                "INSERT INTO t VALUES (2, 'a');",
                "UPDATE p SET active = false WHERE id = 1;",
                "INSERT INTO p VALUES (2, 10, false), (3, 10, true);",
            ],
            assertions: &[
                ScriptTestAssertion {
                    query: "UPDATE dolt_workspace_t SET dolt_staged = TRUE WHERE dolt_diff_type = 'added';",
                    expected: Expected::Error(Diagnostic {
                        code: "23505",
                        message: "duplicate key value violates unique constraint \"ix\"",
                        detail: "Key (lower(s))=(a) already exists.",
                        schema: "public",
                        table: "t",
                        constraint: "ix",
                        ..E
                    }),
                    ..A
                },
                ScriptTestAssertion {
                    query: "UPDATE dolt_workspace_t SET dolt_staged = TRUE;",
                    expected: Expected::Tag("UPDATE 2"),
                    ..A
                },
                ScriptTestAssertion {
                    query: "UPDATE dolt_workspace_p SET dolt_staged = TRUE WHERE to_id = 2;",
                    expected: Expected::Tag("UPDATE 1"),
                    ..A
                },
                ScriptTestAssertion {
                    query: "UPDATE dolt_workspace_p SET dolt_staged = TRUE WHERE to_id = 3;",
                    expected: Expected::Error(Diagnostic {
                        code: "23505",
                        message: "duplicate key value violates unique constraint \"px\"",
                        detail: "Key (u)=(10) already exists.",
                        schema: "public",
                        table: "p",
                        constraint: "px",
                        ..E
                    }),
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT id, u, active FROM p AS OF 'STAGED' ORDER BY id;",
                    expected: Expected::Rows {
                        columns: &[Column("id", INT4), Column("u", INT4), Column("active", BOOL)],
                        rows: &[&[T("1"), T("10"), T("t")], &[T("2"), T("10"), T("f")]],
                        tag: "SELECT 2",
                    },
                    ..A
                },
            ],
            ..S
        },
    ]);
}

#[test]
fn test_sequence_states_that_commits_and_branches_see() {
    run_scripts(&[
        ScriptTest {
            name: "setval then dolt_commit commits the sequence's new state",
            set_up_script: &["CREATE SEQUENCE s;", "SELECT dolt_commit('-Am', 'one');"],
            assertions: &[
                ScriptTestAssertion {
                    query: "SELECT setval('s', 50);",
                    expected: Expected::Rows {
                        columns: &[Column("setval", INT8)],
                        rows: &[
                            &[T("50")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT * FROM dolt_status;",
                    expected: Expected::Rows {
                        columns: &[Column("table_name", TEXT), Column("staged", BOOL), Column("status", TEXT)],
                        rows: &[
                            &[T("sequence public.s"), T("f"), T("modified")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT dolt_commit('-Am', 'two');",
                    expected: Expected::Ok,
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT to_table_name, diff_type FROM dolt_diff_summary('HEAD~1', 'HEAD');",
                    expected: Expected::Rows {
                        columns: &[Column("to_table_name", TEXT), Column("diff_type", TEXT)],
                        rows: &[
                            &[T("sequence public.s"), T("modified")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT * FROM dolt_status;",
                    expected: Expected::Rows {
                        columns: &[Column("table_name", TEXT), Column("staged", BOOL), Column("status", TEXT)],
                        rows: &[
                        ],
                        tag: "SELECT 0",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT nextval('s');",
                    expected: Expected::Rows {
                        columns: &[Column("nextval", INT8)],
                        rows: &[
                            &[T("51")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
            ],
            ..S
        },
        ScriptTest {
            name: "nextval past a log-ahead then dolt_commit commits the sequence's new state",
            set_up_script: &["CREATE SEQUENCE s;", "SELECT dolt_commit('-Am', 'one');"],
            assertions: &[
                ScriptTestAssertion {
                    query: "SELECT max(nextval('s')) FROM generate_series(1, 40);",
                    expected: Expected::Rows {
                        columns: &[Column("max", INT8)],
                        rows: &[
                            &[T("40")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT * FROM dolt_status;",
                    expected: Expected::Rows {
                        columns: &[Column("table_name", TEXT), Column("staged", BOOL), Column("status", TEXT)],
                        rows: &[
                            &[T("sequence public.s"), T("f"), T("modified")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT dolt_commit('-Am', 'two');",
                    expected: Expected::Ok,
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT to_table_name, diff_type FROM dolt_diff_summary('HEAD~1', 'HEAD');",
                    expected: Expected::Rows {
                        columns: &[Column("to_table_name", TEXT), Column("diff_type", TEXT)],
                        rows: &[
                            &[T("sequence public.s"), T("modified")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT * FROM dolt_status;",
                    expected: Expected::Rows {
                        columns: &[Column("table_name", TEXT), Column("staged", BOOL), Column("status", TEXT)],
                        rows: &[
                        ],
                        tag: "SELECT 0",
                    },
                    ..A
                },
            ],
            ..S
        },
        ScriptTest {
            name: "a branch that shares a sequence's storage continues past the values another branch used",
            set_up_script: &["CREATE SEQUENCE s;", "SELECT dolt_commit('-Am', 'one');"],
            assertions: &[
                ScriptTestAssertion {
                    query: "SELECT max(nextval('s')) FROM generate_series(1, 40);",
                    expected: Expected::Rows {
                        columns: &[Column("max", INT8)],
                        rows: &[
                            &[T("40")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT dolt_branch('other');",
                    expected: Expected::Ok,
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT dolt_checkout('other');",
                    expected: Expected::Ok,
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT nextval('s');",
                    expected: Expected::Rows {
                        columns: &[Column("nextval", INT8)],
                        rows: &[
                            &[T("41")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT dolt_checkout('main');",
                    expected: Expected::Ok,
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT nextval('s');",
                    expected: Expected::Rows {
                        columns: &[Column("nextval", INT8)],
                        rows: &[
                            &[T("42")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
            ],
            ..S
        },
    ]);
}

#[test]
fn test_dolt_commit_refuses_the_converters_options_as_unknown_on_a_server_it_did_not_start() {
    run_scripts(&[
        ScriptTest {
            name: "dolt_commit refuses the converter's options as it refuses any unknown option",
            set_up_script: &[
                "CREATE TABLE t (id INT PRIMARY KEY);",
                "SELECT dolt_add('-A');",
            ],
            assertions: &[
                // Doltgrust-specific: Postgres cannot run this, so the Go server's output is expected.
                ScriptTestAssertion {
                    query: "SELECT dolt_commit('-m', 'c', '--parents', 'HEAD');",
                    expected: Expected::Error(Diagnostic { code: "22023", message: "error: unknown option `parents'", ..E }),
                    ..A
                },
                // Doltgrust-specific: Postgres cannot run this, so the Go server's output is expected.
                ScriptTestAssertion {
                    query: "SELECT dolt_commit('-m', 'c', '--committer', 'a <a@b.c>');",
                    expected: Expected::Error(Diagnostic { code: "22023", message: "error: unknown option `committer'", ..E }),
                    ..A
                },
                // Doltgrust-specific: Postgres cannot run this, so the Go server's output is expected.
                ScriptTestAssertion {
                    query: "SELECT dolt_commit('-m', 'c', '--committer-date', '2020-01-01');",
                    expected: Expected::Error(Diagnostic { code: "22023", message: "error: unknown option `committer-date'", ..E }),
                    ..A
                },
                // Doltgrust-specific: Postgres cannot run this, so the Go server's output is expected.
                ScriptTestAssertion {
                    query: "SELECT dolt_commit('-m', 'c', '--replaces', 'abcdefghijklmnopqrstuvwxyz234567');",
                    expected: Expected::Error(Diagnostic { code: "22023", message: "error: unknown option `replaces'", ..E }),
                    ..A
                },
                // Doltgrust-specific: Postgres cannot run this, so the Go server's output is expected.
                ScriptTestAssertion {
                    query: "SELECT dolt_commit('-m', 'c', '--nosuchoption');",
                    expected: Expected::Error(Diagnostic { code: "22023", message: "error: unknown option `nosuchoption'", ..E }),
                    ..A
                },
            ],
            ..S
        },
    ]);
}

#[test]
fn test_dolt_dates_are_instants_shown_in_the_session_time_zone() {
    run_scripts(&[
        ScriptTest {
            name: "a commit's dates are instants that compare with now() and show in the session's time zone",
            intent: "Dolt dates are timestamptz: the commit's UTC instant, comparable with now() and the same instant whatever TimeZone reads it.",
            set_up_script: &[
                "SET TimeZone = 'America/New_York';",
                "CREATE TABLE t (id INT PRIMARY KEY);",
                "SELECT dolt_commit('-Am', 'first');",
            ],
            assertions: &[
                ScriptTestAssertion {
                    query: "SELECT abs(extract(epoch FROM now() - date)) < 60 AS near_now, date <= now() AS not_ahead FROM dolt_log LIMIT 1;",
                    expected: Expected::Rows {
                        columns: &[Column("near_now", BOOL), Column("not_ahead", BOOL)],
                        rows: &[
                            &[T("t"), T("t")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT set_config('test.date', date::text, false) LIKE '%-0_' AS new_york_offset FROM dolt_log LIMIT 1;",
                    expected: Expected::Rows {
                        columns: &[Column("new_york_offset", BOOL)],
                        rows: &[
                            &[T("t")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SET TimeZone = 'Asia/Tokyo';",
                    expected: Expected::Tag("SET"),
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT date = current_setting('test.date')::timestamptz AS same_instant, date::text <> current_setting('test.date') AS other_text, date::text LIKE '%+09' AS tokyo_offset FROM dolt_log LIMIT 1;",
                    expected: Expected::Rows {
                        columns: &[Column("same_instant", BOOL), Column("other_text", BOOL), Column("tokyo_offset", BOOL)],
                        rows: &[
                            &[T("t"), T("t"), T("t")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT abs(extract(epoch FROM now() - date)) < 60 AS near_now FROM dolt_log LIMIT 1;",
                    expected: Expected::Rows {
                        columns: &[Column("near_now", BOOL)],
                        rows: &[
                            &[T("t")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
            ],
            ..S
        },
    ]);
}

#[test]
fn test_dolt_remote_and_dolt_backup_keep_their_configuration_outside_transactions() {
    run_scripts(&[
        ScriptTest {
            name: "dolt_remote and dolt_backup make URLs absolute, keep a git ref, and refuse to run in a transaction block",
            set_up_script: &[
                "SELECT dolt_remote('add', 'hub', 'dolthub/museum');",
                "SELECT dolt_remote('add', 'gh', 'git@github.com:org/repo.git', '--ref', 'refs/dolt/x');",
            ],
            assertions: &[
                // Doltgrust-specific: Postgres cannot run this, so the Go server's output is expected.
                ScriptTestAssertion {
                    query: "SELECT name, url, fetch_specs, params FROM dolt_remotes ORDER BY name;",
                    expected: Expected::Rows {
                        columns: &[Column("name", TEXT), Column("url", TEXT), Column("fetch_specs", JSONB), Column("params", JSONB)],
                        rows: &[
                            &[T("gh"), T("git+ssh://git@github.com/./org/repo.git"), T(r#"["refs/heads/*:refs/remotes/gh/*"]"#), T(r#"{"git_ref": "refs/dolt/x"}"#)],
                            &[T("hub"), T("https://doltremoteapi.dolthub.com/dolthub/museum"), T(r#"["refs/heads/*:refs/remotes/hub/*"]"#), T("{}")],
                        ],
                        tag: "SELECT 2",
                    },
                    ..A
                },
                // Doltgrust-specific: Postgres cannot run this, so the Go server's output is expected.
                ScriptTestAssertion {
                    query: "SELECT dolt_remote('add', 'web', 'https://example.com/x', '--ref', 'refs/dolt/x');",
                    expected: Expected::Error(Diagnostic { code: "22023", message: "error: --ref is only supported for git remotes", ..E }),
                    ..A
                },
                // Doltgrust-specific: Postgres cannot run this, so the Go server's output is expected.
                ScriptTestAssertion {
                    query: "SELECT dolt_backup('add', 'bak', 'https://doltremoteapi.dolthub.com/dolthub/museum');",
                    expected: Expected::Error(Diagnostic { code: "22023", message: "address conflict with a remote: 'hub' -> https://doltremoteapi.dolthub.com/dolthub/museum", ..E }),
                    ..A
                },
                ScriptTestAssertion {
                    query: "BEGIN;",
                    expected: Expected::Tag("BEGIN"),
                    ..A
                },
                // Doltgrust-specific: Postgres cannot run this, so the Go server's output is expected.
                ScriptTestAssertion {
                    query: "SELECT dolt_remote('remove', 'hub');",
                    expected: Expected::Error(Diagnostic { code: "25001", message: "dolt_remote cannot run inside a transaction block", ..E }),
                    ..A
                },
                ScriptTestAssertion {
                    query: "ROLLBACK;",
                    expected: Expected::Tag("ROLLBACK"),
                    ..A
                },
                ScriptTestAssertion {
                    query: "BEGIN;",
                    expected: Expected::Tag("BEGIN"),
                    ..A
                },
                // Doltgrust-specific: Postgres cannot run this, so the Go server's output is expected.
                ScriptTestAssertion {
                    query: "SELECT dolt_backup('add', 'bak', 'https://example.com/bak');",
                    expected: Expected::Error(Diagnostic { code: "25001", message: "dolt_backup cannot run inside a transaction block", ..E }),
                    ..A
                },
                ScriptTestAssertion {
                    query: "ROLLBACK;",
                    expected: Expected::Tag("ROLLBACK"),
                    ..A
                },
                // Doltgrust-specific: Postgres cannot run this, so the Go server's output is expected.
                ScriptTestAssertion {
                    query: "SELECT dolt_remote('remove', 'hub');",
                    expected: Expected::Rows {
                        columns: &[Column("dolt_remote", INT8)],
                        rows: &[
                            &[T("0")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                // Doltgrust-specific: Postgres cannot run this, so the Go server's output is expected.
                ScriptTestAssertion {
                    query: "SELECT name FROM dolt_remotes;",
                    expected: Expected::Rows {
                        columns: &[Column("name", TEXT)],
                        rows: &[
                            &[T("gh")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                // Doltgrust-specific: Postgres cannot run this, so the Go server's output is expected.
                ScriptTestAssertion {
                    query: "SELECT count(*) FROM dolt_remote_branches;",
                    expected: Expected::Rows {
                        columns: &[Column("count", INT8)],
                        rows: &[
                            &[T("0")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                // Doltgrust-specific: Postgres cannot run this, so Doltgrust's output is expected.
                ScriptTestAssertion {
                    query: "SELECT dolt_backup('sync', 'bak');",
                    expected: Expected::Error(Diagnostic { code: "22023", message: "backup 'bak' not found", ..E }),
                    ..A
                },
            ],
            ..S
        },
    ]);
}

