#[test]
fn test_a_merge_stages_its_result_only_without_conflicts() {
    run_scripts(&[
        ScriptTest {
            name: r#"a merge that stops with conflicts stages none of its clean tables"#,
            intent: r#"While a merge's conflicts remain, the staged root keeps its state from before the merge, so a table the merge changed cleanly shows as an unstaged change until it is added, and the commit after resolving and adding holds every table's merged rows."#,
            set_up_script: &[
                r#"CREATE TABLE t (id int PRIMARY KEY, a int);"#,
                r#"CREATE TABLE u (id int PRIMARY KEY, a int);"#,
                r#"INSERT INTO t VALUES (1, 1);"#,
                r#"INSERT INTO u VALUES (1, 1);"#,
                r#"SELECT dolt_commit('-Am', 'base');"#,
                r#"SELECT dolt_branch('feature');"#,
                r#"SELECT dolt_checkout('feature');"#,
                r#"UPDATE t SET a = 10;"#,
                r#"INSERT INTO u VALUES (2, 2);"#,
                r#"SELECT dolt_commit('-am', 'feature');"#,
                r#"SELECT dolt_checkout('main');"#,
                r#"UPDATE t SET a = 11;"#,
                r#"SELECT dolt_commit('-am', 'main');"#,
                r#"SET dolt_allow_commit_conflicts = 1;"#,
            ],
            assertions: &[
                ScriptTestAssertion {
                    query: r#"SELECT fast_forward, conflicts, message FROM dolt_merge('feature');"#,
                    expected: Expected::Rows {
                        columns: &[Column("fast_forward", INT8), Column("conflicts", INT8), Column("message", TEXT)],
                        rows: &[
                            &[T("0"), T("1"), T("conflicts found")],
                        ],
                        tag: "SELECT 1",
                    },
                    notices: &[Diagnostic { severity: "WARNING", code: "01000", message: "merge has unresolved conflicts or constraint violations", ..N }],
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT * FROM dolt_status ORDER BY table_name;"#,
                    expected: Expected::Rows {
                        columns: &[Column("table_name", TEXT), Column("staged", BOOL), Column("status", TEXT)],
                        rows: &[
                            &[T("public.t"), T("f"), T("conflict")],
                            &[T("public.u"), T("f"), T("modified")],
                        ],
                        tag: "SELECT 2",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT count(*) FROM u AS OF 'STAGED';"#,
                    expected: Expected::Rows {
                        columns: &[Column("count", INT8)],
                        rows: &[
                            &[T("1")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT dolt_conflicts_resolve('--ours', 't');"#,
                    expected: Expected::Rows {
                        columns: &[Column("dolt_conflicts_resolve", INT8)],
                        rows: &[
                            &[T("0")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT dolt_add('.');"#,
                    expected: Expected::Rows {
                        columns: &[Column("dolt_add", INT8)],
                        rows: &[
                            &[T("0")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT length(dolt_commit('-m', 'resolved')) > 0 AS committed;"#,
                    expected: Expected::Rows {
                        columns: &[Column("committed", BOOL)],
                        rows: &[
                            &[T("t")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT count(*) FROM u AS OF 'HEAD';"#,
                    expected: Expected::Rows {
                        columns: &[Column("count", INT8)],
                        rows: &[
                            &[T("2")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT count(*) FROM dolt_commit_ancestors WHERE commit_hash = dolt_hashof('HEAD');"#,
                    expected: Expected::Rows {
                        columns: &[Column("count", INT8)],
                        rows: &[
                            &[T("2")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
            ],
            ..S
        },
        ScriptTest {
            name: r#"a merge without a commit and without conflicts stages its changes"#,
            intent: r#"A clean merge with --no-commit stages the merged tables, as Dolt stages a merge that leaves no conflicts."#,
            set_up_script: &[
                r#"CREATE TABLE t (id int PRIMARY KEY, a int);"#,
                r#"CREATE TABLE u (id int PRIMARY KEY, a int);"#,
                r#"INSERT INTO t VALUES (1, 1);"#,
                r#"INSERT INTO u VALUES (1, 1);"#,
                r#"SELECT dolt_commit('-Am', 'base');"#,
                r#"SELECT dolt_branch('feature');"#,
                r#"SELECT dolt_checkout('feature');"#,
                r#"UPDATE t SET a = 10;"#,
                r#"INSERT INTO u VALUES (2, 2);"#,
                r#"SELECT dolt_commit('-am', 'feature');"#,
                r#"SELECT dolt_checkout('main');"#,
                r#"INSERT INTO t VALUES (3, 3);"#,
                r#"SELECT dolt_commit('-am', 'main');"#,
            ],
            assertions: &[
                ScriptTestAssertion {
                    query: r#"SELECT fast_forward, conflicts, message FROM dolt_merge('feature', '--no-commit');"#,
                    expected: Expected::Rows {
                        columns: &[Column("fast_forward", INT8), Column("conflicts", INT8), Column("message", TEXT)],
                        rows: &[
                            &[T("0"), T("0"), T("merge successful")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT * FROM dolt_status ORDER BY table_name;"#,
                    expected: Expected::Rows {
                        columns: &[Column("table_name", TEXT), Column("staged", BOOL), Column("status", TEXT)],
                        rows: &[
                            &[T("public.t"), T("t"), T("modified")],
                            &[T("public.u"), T("t"), T("modified")],
                        ],
                        tag: "SELECT 2",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT count(*) FROM u AS OF 'STAGED';"#,
                    expected: Expected::Rows {
                        columns: &[Column("count", INT8)],
                        rows: &[
                            &[T("2")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
            ],
            ..S
        },
    ]);
}

#[test]
fn test_a_squash_merge_with_schema_conflicts_starts_a_merge() {
    run_scripts(&[
        ScriptTest {
            name: r#"a squash merge that hits schema conflicts starts a merge that can be aborted"#,
            intent: r#"A --squash merge whose tables' definitions conflict records a merge in progress with its schema conflicts, as Dolt does, so that the conflicts can be resolved or the merge aborted."#,
            set_up_script: &[
                r#"CREATE TABLE t (id int PRIMARY KEY, a int);"#,
                r#"INSERT INTO t VALUES (1, 1), (2, 2);"#,
                r#"SELECT dolt_commit('-Am', 'base');"#,
                r#"SELECT dolt_branch('feature');"#,
                r#"SELECT dolt_checkout('feature');"#,
                r#"INSERT INTO t VALUES (3, 3);"#,
                r#"ALTER TABLE t ADD COLUMN extra int;"#,
                r#"SELECT dolt_commit('-am', 'feature');"#,
                r#"SELECT dolt_checkout('main');"#,
                r#"UPDATE t SET a = 20 WHERE id = 2;"#,
                r#"ALTER TABLE t ADD COLUMN extra text;"#,
                r#"SELECT dolt_commit('-am', 'main');"#,
                r#"SET dolt_allow_commit_conflicts = 1;"#,
            ],
            assertions: &[
                ScriptTestAssertion {
                    query: r#"SELECT * FROM dolt_merge('--squash', 'feature');"#,
                    expected: Expected::Rows {
                        columns: &[Column("hash", TEXT), Column("fast_forward", INT8), Column("conflicts", INT8), Column("message", TEXT)],
                        rows: &[
                            &[T(""), T("0"), T("1"), T("conflicts found")],
                        ],
                        tag: "SELECT 1",
                    },
                    notices: &[Diagnostic { severity: "WARNING", code: "01000", message: "merge has unresolved conflicts or constraint violations", ..N }],
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT is_merging, source FROM dolt_merge_status;"#,
                    expected: Expected::Rows {
                        columns: &[Column("is_merging", BOOL), Column("source", TEXT)],
                        rows: &[
                            &[T("t"), T("feature")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT table_name FROM dolt_schema_conflicts;"#,
                    expected: Expected::Rows {
                        columns: &[Column("table_name", TEXT)],
                        rows: &[
                            &[T("public.t")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT * FROM dolt_merge('--abort');"#,
                    expected: Expected::Rows {
                        columns: &[Column("hash", TEXT), Column("fast_forward", INT8), Column("conflicts", INT8), Column("message", TEXT)],
                        rows: &[
                            &[T(""), T("0"), T("0"), T("merge aborted")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT is_merging FROM dolt_merge_status;"#,
                    expected: Expected::Rows {
                        columns: &[Column("is_merging", BOOL)],
                        rows: &[
                            &[T("f")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT id, a, extra FROM t ORDER BY id;"#,
                    expected: Expected::Rows {
                        columns: &[Column("id", INT4), Column("a", INT4), Column("extra", TEXT)],
                        rows: &[
                            &[T("1"), T("1"), Null],
                            &[T("2"), T("20"), Null],
                        ],
                        tag: "SELECT 2",
                    },
                    ..A
                },
            ],
            ..S
        },
    ]);
}

