#[test]
fn test_dolt_diff_of_a_merge_commit_compares_it_with_each_parent() {
    run_scripts(&[
        ScriptTest {
            name: r#"dolt_diff_<t> compares a merge commit with each of its parents"#,
            intent: r#"A merge commit's rows of dolt_diff_<t> are its changes from each parent, as Dolt's history walks every parent: from main's parent, the row side changed, and from side's parent, the row main changed."#,
            set_up_script: &[
                r#"CREATE TABLE t (k int PRIMARY KEY, v text);"#,
                r#"INSERT INTO t VALUES (100, 'a'), (200, 'b');"#,
                r#"SELECT dolt_commit('-Am', 'base');"#,
                r#"SELECT dolt_branch('side');"#,
                r#"SELECT dolt_checkout('side');"#,
                r#"UPDATE t SET v = 'side' WHERE k = 200;"#,
                r#"SELECT dolt_commit('-am', 'sidec');"#,
                r#"SELECT dolt_checkout('main');"#,
                r#"UPDATE t SET v = 'main' WHERE k = 100;"#,
                r#"SELECT dolt_commit('-am', 'mainc');"#,
                r#"SELECT dolt_merge('side');"#,
            ],
            assertions: &[
                ScriptTestAssertion {
                    query: r#"SELECT d.to_k, d.from_v, d.to_v, d.dolt_diff_type, l.message FROM dolt_diff_t d JOIN dolt_log l ON l.commit_hash = d.dolt_from_commit WHERE d.dolt_to_commit = dolt_hashof('HEAD') ORDER BY d.to_k;"#,
                    expected: Expected::Rows {
                        columns: &[Column("to_k", INT4), Column("from_v", TEXT), Column("to_v", TEXT), Column("dolt_diff_type", TEXT), Column("message", TEXT)],
                        rows: &[
                            &[T("100"), T("a"), T("main"), T("modified"), T("sidec")],
                            &[T("200"), T("b"), T("side"), T("modified"), T("mainc")],
                        ],
                        tag: "SELECT 2",
                    },
                    ..A
                },
            ],
            ..S
        },
    ]);
}

