#[test]
fn test_a_merge_combines_column_properties_and_checks_a_merged_not_null_against_the_rows() {
    run_scripts(&[
        ScriptTest {
            name: "a merged NOT NULL from one side and DEFAULT from the other records a violation for a NULL row",
            intent: "Both sides recreated t, one with v NOT NULL and the other with v DEFAULT 'x' and a NULL row, which pair as one table and combine into v NOT NULL DEFAULT 'x', so the NULL row becomes a not null violation rather than a broken constraint.",
            set_up_script: &[
                "CREATE TABLE t (id INT PRIMARY KEY, v TEXT);",
                "INSERT INTO t VALUES (1, 'a');",
                "SELECT dolt_commit('-Am', 'ancestor');",
                "SELECT dolt_branch('feat');",
                "SELECT dolt_checkout('feat');",
                "DROP TABLE t;",
                "CREATE TABLE t (id INT PRIMARY KEY, v TEXT NOT NULL);",
                "INSERT INTO t VALUES (1, 'a');",
                "SELECT dolt_commit('-Am', 'feat');",
                "SELECT dolt_checkout('main');",
                "DROP TABLE t;",
                "CREATE TABLE t (id INT PRIMARY KEY, v TEXT DEFAULT 'x');",
                "INSERT INTO t VALUES (1, 'a'), (2, NULL);",
                "SELECT dolt_commit('-Am', 'main');",
                "SET dolt_force_transaction_commit = on;",
            ],
            assertions: &[
                ScriptTestAssertion {
                    query: "SELECT to_table_name, from_table_name, diff_type FROM dolt_diff_summary('HEAD~1', 'HEAD');",
                    expected: Expected::Rows {
                        columns: &[Column("to_table_name", TEXT), Column("from_table_name", TEXT), Column("diff_type", TEXT)],
                        rows: &[
                            &[T("public.t"), T("public.t"), T("modified")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT conflicts FROM dolt_merge('feat');",
                    expected: Expected::Rows {
                        columns: &[Column("conflicts", INT8)],
                        rows: &[
                            &[T("1")],
                        ],
                        tag: "SELECT 1",
                    },
                    notices: &[Diagnostic { severity: "WARNING", code: "01000", message: "merge has unresolved conflicts or constraint violations", ..N }],
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT pg_get_expr(d.adbin, d.adrelid), a.attnotnull FROM pg_attribute a JOIN pg_attrdef d ON d.adrelid = a.attrelid AND d.adnum = a.attnum WHERE a.attrelid = 't'::regclass AND a.attname = 'v';",
                    expected: Expected::Rows {
                        columns: &[Column("pg_get_expr", TEXT), Column("attnotnull", BOOL)],
                        rows: &[
                            &[T("'x'::text"), T("t")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT dolt_violation_type, id, v FROM dolt_constraint_violations_t;",
                    expected: Expected::Rows {
                        columns: &[Column("dolt_violation_type", TEXT), Column("id", INT4), Column("v", TEXT)],
                        rows: &[
                            &[T("not null"), T("2"), Null],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
            ],
            ..S
        },
    ]);
}

#[test]
fn test_resolving_a_schema_conflict_with_ours_takes_our_whole_table() {
    run_scripts(&[
        ScriptTest {
            name: "dolt_conflicts_resolve --ours on a schema conflict takes our definition and our rows",
            intent: "Resolving a schema conflict with --ours takes our whole table, as git's checkout --ours takes the whole file, so none of theirs' rows or edits remain under our definition.",
            set_up_script: &[
                "CREATE TABLE t (id INT PRIMARY KEY, v TEXT);",
                "INSERT INTO t VALUES (1, 'a'), (2, 'b');",
                "SELECT dolt_commit('-Am', 'ancestor');",
                "SELECT dolt_branch('feat');",
                "SELECT dolt_checkout('feat');",
                "ALTER TABLE t ADD COLUMN extra TEXT;",
                "UPDATE t SET v = 'theirs', extra = 'te' WHERE id = 1;",
                "INSERT INTO t VALUES (3, 'theirs new', 'x');",
                "SELECT dolt_commit('-Am', 'feat');",
                "SELECT dolt_checkout('main');",
                "ALTER TABLE t ADD COLUMN extra INTEGER;",
                "UPDATE t SET v = 'ours' WHERE id = 2;",
                "SELECT dolt_commit('-Am', 'main');",
                "SET dolt_allow_commit_conflicts = on;",
            ],
            assertions: &[
                ScriptTestAssertion {
                    query: "SELECT conflicts FROM dolt_merge('feat');",
                    expected: Expected::Rows {
                        columns: &[Column("conflicts", INT8)],
                        rows: &[
                            &[T("1")],
                        ],
                        tag: "SELECT 1",
                    },
                    notices: &[Diagnostic { severity: "WARNING", code: "01000", message: "merge has unresolved conflicts or constraint violations", ..N }],
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT dolt_conflicts_resolve('--ours', 't');",
                    expected: Expected::Ok,
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT * FROM t ORDER BY id;",
                    expected: Expected::Rows {
                        columns: &[Column("id", INT4), Column("v", TEXT), Column("extra", INT4)],
                        rows: &[
                            &[T("1"), T("a"), Null],
                            &[T("2"), T("ours"), Null],
                        ],
                        tag: "SELECT 2",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT count(*) FROM dolt_schema_conflicts;",
                    expected: Expected::Rows {
                        columns: &[Column("count", INT8)],
                        rows: &[
                            &[T("0")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
            ],
            ..S
        },
    ]);
}

