#[test]
fn test_merging_views_another_branch_recreated_with_other_columns() {
    run_scripts(&[
        ScriptTest {
            name: "a view or materialized view only theirs recreated with other columns, or in another order, merges with theirs' columns",
            set_up_script: &[
                "CREATE TABLE t (a INT PRIMARY KEY, b INT);",
                "INSERT INTO t VALUES (1, 10), (2, 20);",
                "CREATE VIEW v AS SELECT a FROM t;",
                "CREATE VIEW w AS SELECT a, b FROM t;",
                "CREATE MATERIALIZED VIEW mv AS SELECT a FROM t;",
                "SELECT dolt_commit('-Am', 'base');",
                "SELECT dolt_checkout('-b', 'feature');",
                "DROP VIEW v;",
                "CREATE VIEW v AS SELECT b FROM t;",
                "DROP VIEW w;",
                "CREATE VIEW w AS SELECT b, a FROM t;",
                "DROP MATERIALIZED VIEW mv;",
                "CREATE MATERIALIZED VIEW mv AS SELECT b FROM t;",
                "SELECT dolt_commit('-Am', 'feature');",
                "SELECT dolt_checkout('main');",
                "INSERT INTO t VALUES (3, 30);",
                "SELECT dolt_commit('-Am', 'main');",
            ],
            assertions: &[
                ScriptTestAssertion {
                    query: "SELECT fast_forward, conflicts FROM dolt_merge('feature');",
                    expected: Expected::Rows {
                        columns: &[Column("fast_forward", INT8), Column("conflicts", INT8)],
                        rows: &[
                            &[T("0"), T("0")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT attrelid::regclass::text, attnum, attname FROM pg_attribute WHERE attrelid IN ('v'::regclass, 'w'::regclass, 'mv'::regclass) AND attnum > 0 ORDER BY 1, 2;",
                    expected: Expected::Rows {
                        columns: &[Column("attrelid", TEXT), Column("attnum", INT2), Column("attname", NAME)],
                        rows: &[
                            &[T("mv"), T("1"), T("b")],
                            &[T("v"), T("1"), T("b")],
                            &[T("w"), T("1"), T("b")],
                            &[T("w"), T("2"), T("a")],
                        ],
                        tag: "SELECT 4",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT * FROM v ORDER BY 1;",
                    expected: Expected::Rows {
                        columns: &[Column("b", INT4)],
                        rows: &[
                            &[T("10")],
                            &[T("20")],
                            &[T("30")],
                        ],
                        tag: "SELECT 3",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT * FROM w ORDER BY 1;",
                    expected: Expected::Rows {
                        columns: &[Column("b", INT4), Column("a", INT4)],
                        rows: &[
                            &[T("10"), T("1")],
                            &[T("20"), T("2")],
                            &[T("30"), T("3")],
                        ],
                        tag: "SELECT 3",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "REFRESH MATERIALIZED VIEW mv;",
                    expected: Expected::Tag("REFRESH MATERIALIZED VIEW"),
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT * FROM mv ORDER BY 1;",
                    expected: Expected::Rows {
                        columns: &[Column("b", INT4)],
                        rows: &[
                            &[T("10")],
                            &[T("20")],
                            &[T("30")],
                        ],
                        tag: "SELECT 3",
                    },
                    ..A
                },
            ],
            ..S
        },
    ]);
}

#[test]
fn test_dolt_branch_deletes_remote_tracking_branches_only_by_their_remote_and_branch() {
    run_scripts(&[
        ScriptTest {
            name: "dolt_branch -d -r refuses a name without a remote and a branch, and a remote-tracking branch that doesn't exist",
            assertions: &[
                // Doltgrust-specific: Postgres cannot run this, so the Go server's output is expected.
                ScriptTestAssertion {
                    query: "SELECT dolt_branch('-d', '-r', 'nope/x');",
                    expected: Expected::Error(Diagnostic { code: "22023", message: "branch not found", ..E }),
                    ..A
                },
                // Doltgrust-specific: Postgres cannot run this, so the Go server's output is expected.
                ScriptTestAssertion {
                    query: "SELECT dolt_branch('-D', '-r', 'remotes/nope/x');",
                    expected: Expected::Error(Diagnostic { code: "22023", message: "branch not found", ..E }),
                    ..A
                },
                // Doltgrust-specific: Postgres cannot run this, so the Go server's output is expected.
                ScriptTestAssertion {
                    query: "SELECT dolt_branch('-d', '-r', 'bad');",
                    expected: Expected::Error(Diagnostic { code: "22023", message: "invalid ref spec", ..E }),
                    ..A
                },
                // Doltgrust-specific: Postgres cannot run this, so the Go server's output is expected.
                ScriptTestAssertion {
                    query: "SELECT dolt_branch('-d', '-r', 'origin/');",
                    expected: Expected::Error(Diagnostic { code: "22023", message: "invalid ref spec", ..E }),
                    ..A
                },
                // Doltgrust-specific: Postgres cannot run this, so the Go server's output is expected.
                ScriptTestAssertion {
                    query: "SELECT dolt_branch('-r', '-d');",
                    expected: Expected::Error(Diagnostic { code: "22023", message: "error: invalid usage", ..E }),
                    ..A
                },
            ],
            ..S
        },
    ]);
}

