#[test]
fn test_merging_constraints_and_indexes_both_branches_changed_differently_merges_them_field_by_field() {
    run_scripts(&[
        ScriptTest {
            name: "a constraint or index each branch changed in a different part merges both changes, and one renamed differently on each branch conflicts",
            set_up_script: &[
                "CREATE TABLE p (id INT PRIMARY KEY);",
                "CREATE TABLE t (id INT PRIMARY KEY, v INT NOT NULL, pid INT);",
                "CREATE UNIQUE INDEX ti ON t (v);",
                "ALTER TABLE t ADD CONSTRAINT ck CHECK (v > 0) NOT VALID;",
                "ALTER TABLE t ADD CONSTRAINT fk FOREIGN KEY (pid) REFERENCES p (id);",
                "ALTER TABLE t ADD CONSTRAINT ck2 CHECK (v < 1000);",
                "INSERT INTO t VALUES (1, 5, NULL);",
                "SELECT dolt_commit('-Am', 'base');",
                "SELECT dolt_checkout('-b', 'other');",
                "ALTER TABLE t VALIDATE CONSTRAINT ck;",
                "ALTER TABLE t ALTER CONSTRAINT fk DEFERRABLE INITIALLY DEFERRED;",
                "ALTER TABLE t REPLICA IDENTITY USING INDEX ti;",
                "SELECT dolt_commit('-am', 'theirs');",
                "SELECT dolt_checkout('-b', 'renamed', 'main');",
                "ALTER TABLE t RENAME CONSTRAINT ck2 TO a_name;",
                "SELECT dolt_commit('-am', 'renamed');",
                "SELECT dolt_checkout('main');",
                "ALTER TABLE t RENAME CONSTRAINT ck TO ck_renamed;",
                "ALTER TABLE t RENAME CONSTRAINT fk TO fk_renamed;",
                "ALTER TABLE t RENAME CONSTRAINT ck2 TO b_name;",
                "ALTER TABLE t CLUSTER ON ti;",
                "SELECT dolt_commit('-am', 'ours');",
            ],
            assertions: &[
                ScriptTestAssertion {
                    query: "SELECT conflicts, message FROM dolt_merge('other');",
                    expected: Expected::Rows {
                        columns: &[Column("conflicts", INT8), Column("message", TEXT)],
                        rows: &[
                            &[T("0"), T("merge successful")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT conname, convalidated, condeferrable, condeferred FROM pg_constraint WHERE conrelid = 't'::regclass AND contype IN ('c', 'f') ORDER BY conname;",
                    expected: Expected::Rows {
                        columns: &[Column("conname", NAME), Column("convalidated", BOOL), Column("condeferrable", BOOL), Column("condeferred", BOOL)],
                        rows: &[
                            &[T("b_name"), T("t"), T("f"), T("f")],
                            &[T("ck_renamed"), T("t"), T("f"), T("f")],
                            &[T("fk_renamed"), T("t"), T("t"), T("t")],
                        ],
                        tag: "SELECT 3",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT indisclustered, indisreplident FROM pg_index WHERE indexrelid = 'ti'::regclass;",
                    expected: Expected::Rows {
                        columns: &[Column("indisclustered", BOOL), Column("indisreplident", BOOL)],
                        rows: &[
                            &[T("t"), T("t")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SET dolt_allow_commit_conflicts = on;",
                    expected: Expected::Tag("SET"),
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT conflicts, message FROM dolt_merge('renamed');",
                    expected: Expected::Rows {
                        columns: &[Column("conflicts", INT8), Column("message", TEXT)],
                        rows: &[
                            &[T("1"), T("conflicts found")],
                        ],
                        tag: "SELECT 1",
                    },
                    notices: &[Diagnostic { severity: "WARNING", code: "01000", message: "merge has unresolved conflicts or constraint violations", ..N }],
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT description FROM dolt_schema_conflicts;",
                    expected: Expected::Rows {
                        columns: &[Column("description", TEXT)],
                        rows: &[
                            &[T("two checks with the name 'b_name' but different definitions")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
            ],
            ..S
        },
    ]);
}

#[test]
fn test_criss_cross_merge_bases_that_changed_a_primary_key_differently_fold_into_the_base_key() {
    run_scripts(&[
        ScriptTest {
            name: "merge bases that changed a table's primary key differently fold into a virtual base with the older base's key, so the tips' merge conflicts on the key as Dolt's does",
            set_up_script: &[
                "SET dolt_allow_commit_conflicts = on;",
                "CREATE TABLE t (a INT NOT NULL, b INT NOT NULL, c INT NOT NULL, PRIMARY KEY (a));",
                "INSERT INTO t VALUES (1, 10, 100), (2, 20, 200);",
                "SELECT dolt_commit('-Am', 'B');",
                "SELECT dolt_branch('y');",
                "SELECT dolt_checkout('-b', 'x');",
                "ALTER TABLE t DROP CONSTRAINT t_pkey, ADD PRIMARY KEY (b);",
                "SELECT dolt_commit('-Am', 'X1');",
                "SELECT dolt_branch('x1');",
                "SELECT dolt_checkout('y');",
                "ALTER TABLE t DROP CONSTRAINT t_pkey, ADD PRIMARY KEY (c);",
                "SELECT dolt_commit('-Am', 'Y1');",
                "SELECT dolt_branch('y1');",
                "SELECT dolt_checkout('x');",
                "SELECT dolt_merge('y1');",
                "SELECT dolt_conflicts_resolve('--ours', 't');",
                "SELECT dolt_commit('-Am', 'Mx');",
                "SELECT dolt_checkout('y');",
                "SELECT dolt_merge('x1');",
                "SELECT dolt_conflicts_resolve('--ours', 't');",
                "SELECT dolt_commit('-Am', 'My');",
                "INSERT INTO t VALUES (3, 30, 300);",
                "SELECT dolt_commit('-am', 'y more');",
                "SELECT dolt_checkout('x');",
                "INSERT INTO t VALUES (4, 40, 400);",
                "SELECT dolt_commit('-am', 'x more');",
            ],
            assertions: &[
                ScriptTestAssertion {
                    query: "SELECT conflicts, message FROM dolt_merge('y');",
                    expected: Expected::Rows {
                        columns: &[Column("conflicts", INT8), Column("message", TEXT)],
                        rows: &[
                            &[T("1"), T("conflicts found")],
                        ],
                        tag: "SELECT 1",
                    },
                    notices: &[Diagnostic { severity: "WARNING", code: "01000", message: "merge has unresolved conflicts or constraint violations", ..N }],
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT table_name, description FROM dolt_schema_conflicts;",
                    expected: Expected::Rows {
                        columns: &[Column("table_name", TEXT), Column("description", TEXT)],
                        rows: &[
                            &[T("public.t"), T("cannot merge because table t has different primary keys")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
            ],
            ..S
        },
    ]);
}

#[test]
fn test_merging_a_table_one_branch_dropped_and_the_other_changed_keeps_ours_until_resolved() {
    run_scripts(&[
        ScriptTest {
            name: "a merge of a table one branch dropped and the other changed keeps our side's table in the working state with a schema conflict, as Dolt does, and each resolution finds the table by name",
            set_up_script: &[
                "SET dolt_allow_commit_conflicts = on;",
                "CREATE TABLE t (pk INT PRIMARY KEY, v INT);",
                "INSERT INTO t VALUES (1, 1);",
                "SELECT dolt_commit('-Am', 'base');",
                "SELECT dolt_branch('dropper');",
                "UPDATE t SET v = 2;",
                "SELECT dolt_commit('-Am', 'main changes t');",
                "SELECT dolt_checkout('dropper');",
                "DROP TABLE t;",
                "SELECT dolt_commit('-Am', 'dropper drops t');",
                "SELECT dolt_checkout('main');",
            ],
            assertions: &[
                ScriptTestAssertion {
                    query: "SELECT conflicts FROM dolt_merge('dropper');",
                    expected: Expected::Rows { columns: &[Column("conflicts", INT8)], rows: &[&[T("1")]], tag: "SELECT 1" },
                    notices: &[Diagnostic { severity: "WARNING", code: "01000", message: "merge has unresolved conflicts or constraint violations", ..N }],
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT * FROM t;",
                    expected: Expected::Rows { columns: &[Column("pk", INT4), Column("v", INT4)], rows: &[&[T("1"), T("2")]], tag: "SELECT 1" },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT table_name, status FROM dolt_status;",
                    expected: Expected::Rows {
                        columns: &[Column("table_name", TEXT), Column("status", TEXT)],
                        rows: &[
                            &[T("public.t"), T("schema conflict")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT dolt_conflicts_resolve('--theirs', 't');",
                    expected: Expected::Rows { columns: &[Column("dolt_conflicts_resolve", INT8)], rows: &[&[T("0")]], tag: "SELECT 1" },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT to_regclass('t') IS NULL AS dropped;",
                    expected: Expected::Rows { columns: &[Column("dropped", BOOL)], rows: &[&[T("t")]], tag: "SELECT 1" },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT dolt_merge('--abort');",
                    expected: Expected::Ok,
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT dolt_checkout('dropper');",
                    expected: Expected::Ok,
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT conflicts FROM dolt_merge('main');",
                    expected: Expected::Rows { columns: &[Column("conflicts", INT8)], rows: &[&[T("1")]], tag: "SELECT 1" },
                    notices: &[Diagnostic { severity: "WARNING", code: "01000", message: "merge has unresolved conflicts or constraint violations", ..N }],
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT dolt_conflicts_resolve('--theirs', 't');",
                    expected: Expected::Rows { columns: &[Column("dolt_conflicts_resolve", INT8)], rows: &[&[T("0")]], tag: "SELECT 1" },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT * FROM t;",
                    expected: Expected::Rows { columns: &[Column("pk", INT4), Column("v", INT4)], rows: &[&[T("1"), T("2")]], tag: "SELECT 1" },
                    ..A
                },
            ],
            ..S
        },
    ]);
}

